    case(range)
      2'b00: range <= ovf ? 2'b01 : 2'b00;
      2'b01: begin
        if (ovf) range <= 2'b10;
        if (unf) range <= 2'b00;
      end
      2'b10: begin
        if (ovf) range <= 2'b11;
        if (unf) range <= 2'b01;
      end
      2'b11: range <= unf ? 2'b10 : 2'b11;
