module adaptive_baud_detector (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    output logic baud_locked,
    output logic [19:0] measured_baud_period,
    output logic data_ready
);

typedef enum logic [3:0] {
    IDLE,
    WAIT_FOR_START,
    MEASURE_START,
    MEASURE_BIT0,
    MEASURE_BIT1,
    MEASURE_BIT2,
    VERIFY,
    LOCKED,
    ERROR
} state_t;

state_t state, next_state;
logic [19:0] period_counter;
logic [19:0] accumulated_period;
logic [2:0] bit_sample_count;
logic [19:0] bit_periods [0:7];
logic [3:0] measurement_index;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        period_counter <= 20'b0;
        accumulated_period <= 20'b0;
        bit_sample_count <= 3'b0;
        measurement_index <= 4'b0;
    end else begin
        state <= next_state;

        // Counter logic based on state
        unique case (state)
            IDLE: period_counter <= 20'b0;

            WAIT_FOR_START: begin
                if (!rx_line)  // Start bit detected
                    period_counter <= period_counter + 1;
                else
                    period_counter <= 20'b0;
            end

            MEASURE_START: begin
                if (!rx_line)
                    period_counter <= period_counter + 1;
            end

            MEASURE_BIT0, MEASURE_BIT1, MEASURE_BIT2: begin
                period_counter <= period_counter + 1;
                if (measurement_index < 8 && rx_line != (state == MEASURE_BIT0)) begin
                    bit_periods[measurement_index] <= period_counter;
                    measurement_index <= measurement_index + 1;
                end
            end

            VERIFY: begin
                accumulated_period <= (bit_periods[0] + bit_periods[1] +
                                      bit_periods[2] + bit_periods[3]) >> 2;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    baud_locked = 1'b0;
    data_ready = 1'b0;
    measured_baud_period = accumulated_period;

    // Statistical analysis variables
    logic [19:0] avg_period;
    logic [19:0] deviation;

    avg_period = (bit_periods[0] + bit_periods[1] + bit_periods[2] +
                  bit_periods[3] + bit_periods[4] + bit_periods[5] +
                  bit_periods[6] + bit_periods[7]) >> 3;

    deviation = 0;
    for (int i = 0; i < 8; i++) begin
        if (bit_periods[i] > avg_period)
            deviation = deviation + (bit_periods[i] - avg_period);
        else
            deviation = deviation + (avg_period - bit_periods[i]);
    end
    deviation = deviation >> 3;

    case (state)
        IDLE: begin
            if (!rx_line)
                next_state = WAIT_FOR_START;
        end

        WAIT_FOR_START: begin
            if (rx_line) begin
                if (period_counter > 100)  // Valid start bit length
                    next_state = MEASURE_START;
                else
                    next_state = ERROR;  // Glitch detected
            end
        end

        MEASURE_START: begin
            if (rx_line) begin
                bit_periods[0] = period_counter;
                measurement_index = 4'b1;
                next_state = MEASURE_BIT0;
                period_counter = 20'b0;
            end
        end

        MEASURE_BIT0, MEASURE_BIT1, MEASURE_BIT2: begin
            if (rx_line != (state == MEASURE_BIT0)) begin
                if (measurement_index < 8) begin
                    bit_periods[measurement_index] = period_counter;
                    period_counter = 20'b0;

                    if (measurement_index == 7)
                        next_state = VERIFY;
                end
            end

            // Timeout detection
            if (period_counter > avg_period * 2 && avg_period != 0)
                next_state = ERROR;
        end

        VERIFY: begin
            // Check if measurements are consistent (low deviation)
            if (deviation < (avg_period >> 3)) begin  // Within 12.5% tolerance
                next_state = LOCKED;
                measured_baud_period = avg_period;
                baud_locked = 1'b1;  // Lock immediately
                data_ready = 1'b1;
            end else begin
                next_state = ERROR;
            end
        end

        LOCKED: begin
            baud_locked = 1'b1;
            measured_baud_period = avg_period;

            // Monitor for baud rate changes
            if (!rx_line && period_counter > measured_baud_period * 3/2)
                next_state = IDLE;  // Re-detect if new start bit with different timing
        end

        ERROR: begin
            // Reset after error
            if (rx_line)
                next_state = IDLE;
        end
    endcase
end

endmodule,"module adaptive_baud_detector_asserts  (input logic clk,

module pwm_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] period,
    input logic [7:0] duty_cycle,
    input logic update_duty,
    output logic pwm_out
);

typedef enum logic [1:0] {HIGH, LOW, UPDATE} state_t;
state_t state, next_state;
logic [7:0] counter;
logic [7:0] current_duty;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= LOW;
        counter <= 8'b0;
        current_duty <= 8'b0;
    end else begin
        state <= next_state;
        counter <= counter + 1;
        if (update_duty)
            current_duty <= duty_cycle;
    end
end

always_comb begin
    next_state = state;
    pwm_out = 1'b0;

    case (state)
        HIGH: begin
            pwm_out = 1'b1;
            if (counter == current_duty - 1) begin
                next_state = LOW;
                pwm_out = 1'b0;  // Immediate transition
            end
            if (update_duty && counter < duty_cycle)
                pwm_out = 1'b1;  // Immediate duty cycle update
        end

        LOW: begin
            pwm_out = 1'b0;
            if (counter == period - 1) begin
                next_state = HIGH;
                counter = 8'b0;
                pwm_out = 1'b1;  // Immediate transition
            end
            if (update_duty && duty_cycle > 0)
                next_state = UPDATE;  // Special update state
        end

        UPDATE: begin
            pwm_out = 1'b1;  // Immediate response to new duty cycle
            next_state = HIGH;
            counter = 8'b0;
        end
    endcase
end

endmodule,"module pwm_generator_mealy_asserts  (input logic clk,

module vending_machine_mealy (
    input logic clk,
    input logic rst_n,
    input logic coin_25,  // Quarter
    input logic coin_10,  // Dime
    output logic dispense
);

typedef enum logic [1:0] {S0, S25, S35} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    dispense = 1'b0;

    case (state)
        S0: begin
            if (coin_25) next_state = S25;
            else if (coin_10) next_state = S10;
        end

        S10: begin
            if (coin_25) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
            else if (coin_10) next_state = S20;
        end

        S20: begin
            if (coin_25) begin
                next_state = S45;
                dispense = 1'b1;  // Total = 45 cents - dispense with change
            end
            else if (coin_10) next_state = S30;
        end

        S25: begin
            if (coin_10) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
        end

        S30, S35, S45: begin
            // After dispense, go back to S0
            next_state = S0;
        end
    endcase
end

endmodule,"module vending_machine_mealy_asserts  (input logic clk,

module seq_detector_1001_nonoverlap (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [2:0] {S0, S1, S10, S100} state_t;
state_t state, next_state;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: next_state = din ? S1 : S0;

        S1: next_state = din ? S1 : S10;

        S10: next_state = din ? S1 : S100;

        S100: begin
            if (din) begin
                next_state = S1;  // Start new sequence from last '1'
                detected = 1'b1;  // Pattern "1001" detected
            end else begin
                next_state = S0;   // Reset if next bit is 0
            end
        end
    endcase
end

