module uart_sampler_mealy (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    input logic sample_enable,
    output logic bit_value,
    output logic bit_ready
);

typedef enum logic [2:0] {IDLE, START, MIDDLE, SAMPLE} state_t;
state_t state, next_state;
logic [2:0] oversample_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        oversample_count <= 3'b0;
    end else begin
        state <= next_state;
        if (sample_enable)
            oversample_count <= oversample_count + 1;
    end
end

always_comb begin
    next_state = state;
    bit_value = 1'b0;
    bit_ready = 1'b0;

    case (state)
        IDLE: begin
            if (!rx_line && sample_enable)  // Start bit detected
                next_state = START;
        end

        START: begin
            if (sample_enable) begin
                if (oversample_count == 3'b100) begin  // Middle of start bit
                    next_state = MIDDLE;
                end
            end
        end

        MIDDLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111) begin  // Sample point
                    next_state = SAMPLE;
                    bit_value = rx_line;  // Sample the bit
                    bit_ready = 1'b1;     // Bit ready immediately
                end
            end
        end

        SAMPLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111)
                    next_state = IDLE;
                else
                    next_state = MIDDLE;
            end
        end
    endcase
end

endmodule,"module uart_sampler_mealy_asserts  (input logic clk,

module jpeg_huffman_encoder (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_byte,           // Input data byte
    input logic [5:0] run_length,           // Run length of zeros
    input logic [3:0] category,              // Category of non-zero value
    input logic [11:0] amplitude,            // Amplitude of non-zero value
    input logic valid_in,
    input logic last_block,
    output logic [15:0] encoded_bits,        // Huffman encoded bits
    output logic [3:0] bit_length,           // Length of encoded bits (1-16)
    output logic [3:0] code_count,           // Number of codes generated
    output logic done,
    output logic eob_detected
);

typedef enum logic [3:0] {
    IDLE,
    GET_DC_DIFF,
    ENCODE_DC,
    GET_AC_COEFF,
    ENCODE_AC_RUN,
    ENCODE_AC_SIZE,
    ENCODE_AC_AMPLITUDE,
    CHECK_EOB,
    INSERT_EOB,
    FLUSH,
    COMPLETE,
    WAIT
} state_t;

state_t state, next_state;
logic [15:0] huffman_code;
logic [3:0] huffman_len;
logic [5:0] zero_run;
logic [3:0] size_category;
logic [11:0] value_amplitude;
logic [2:0] ac_counter;
logic [7:0] bit_buffer;
logic [3:0] bit_pos;
logic [3:0] code_counter;

// Huffman tables (simplified JPEG tables)
typedef struct {
    logic [15:0] code;
    logic [3:0] length;
} huffman_entry_t;

// DC Huffman table (luminance)
huffman_entry_t dc_table [0:11] = '{
    '{16'h0000, 4'd2},  // 00
    '{16'h0002, 4'd3},  // 010
    '{16'h0003, 4'd3},  // 011
    '{16'h0004, 4'd3},  // 100
    '{16'h0005, 4'd3},  // 101
    '{16'h0006, 4'd3},  // 110
    '{16'h000E, 4'd4},  // 1110
    '{16'h001E, 4'd5},  // 11110
    '{16'h003E, 4'd6},  // 111110
    '{16'h007E, 4'd7},  // 1111110
    '{16'h00FE, 4'd8},  // 11111110
    '{16'h01FE, 4'd9}   // 111111110
};

// AC Huffman table (luminance) - simplified
huffman_entry_t ac_table [0:255] = '{
    // Run/Size combinations
    '{16'h0000, 4'd4},  // EOB
    '{16'h0001, 4'd2},  // 0/1
    '{16'h0002, 4'd2},  // 0/2
    '{16'h0003, 4'd3},  // 0/3
    // ... more entries (simplified for example)
    default: '{16'hFFFF, 4'd16}
};

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        huffman_code <= 16'b0;
        huffman_len <= 4'b0;
        zero_run <= 6'b0;
        size_category <= 4'b0;
        value_amplitude <= 12'b0;
        ac_counter <= 3'b0;
        bit_buffer <= 8'b0;
        bit_pos <= 4'b0;
        code_counter <= 4'b0;
    end else begin
        state <= next_state;

        // Capture input data
        if (valid_in && state == IDLE) begin
            size_category <= category;
            zero_run <= run_length;
            value_amplitude <= amplitude;
        end

        // Update counters
        if (state == ENCODE_DC || state == ENCODE_AC_SIZE)
            code_counter <= code_counter + 1;

        if (state == ENCODE_AC_RUN)
            ac_counter <= ac_counter + 1;
    end
end

always_comb begin
    next_state = state;
    encoded_bits = huffman_code;
    bit_length = huffman_len;
    code_count = code_counter;
    done = 1'b0;
    eob_detected = 1'b0;

    // Huffman encoding logic
    logic [15:0] temp_code;
    logic [3:0] temp_len;
    logic [11:0] temp_amplitude;

    case (state)
        IDLE: begin
            code_counter = 4'b0;
            if (valid_in) begin
                next_state = GET_DC_DIFF;
            end
        end

        GET_DC_DIFF: begin
            // Get DC coefficient difference category
            if (size_category < 12) begin
                huffman_code = dc_table[size_category].code;
                huffman_len = dc_table[size_category].length;
                next_state = ENCODE_DC;
            end else begin
                next_state = WAIT;
            end
        end

        ENCODE_DC: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            // Append amplitude bits
            if (size_category > 0) begin
                temp_amplitude = value_amplitude;
                // Encode amplitude in lower bits
                encoded_bits = (huffman_code << size_category) |
                              (temp_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = GET_AC_COEFF;
            ac_counter = 3'b0;
        end

        GET_AC_COEFF: begin
            if (ac_counter < 8) begin  // Max 8 AC coefficients per block
                if (zero_run > 0) begin
                    // Encode run-length of zeros
                    next_state = ENCODE_AC_RUN;
                end else if (size_category > 0) begin
                    // Encode non-zero AC coefficient
                    next_state = ENCODE_AC_SIZE;
                end else begin
                    // Skip to next coefficient
                    ac_counter = ac_counter + 1;
                end
            end else begin
                next_state = CHECK_EOB;
            end
        end

        ENCODE_AC_RUN: begin
            // Encode run-length of zeros (simplified)
            temp_code = ac_table[zero_run * 16 + size_category].code;
            temp_len = ac_table[zero_run * 16 + size_category].length;

            if (temp_len > 0) begin
                huffman_code = temp_code;
                huffman_len = temp_len;
                next_state = ENCODE_AC_SIZE;
            end else begin
                // Use extended run-length encoding
                next_state = ENCODE_AC_SIZE;
            end
        end

        ENCODE_AC_SIZE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            if (size_category > 0) begin
                // Encode amplitude for AC coefficient
                encoded_bits = (huffman_code << size_category) |
                              (value_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = ENCODE_AC_AMPLITUDE;
        end

        ENCODE_AC_AMPLITUDE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            ac_counter = ac_counter + 1;
            next_state = GET_AC_COEFF;
        end

        CHECK_EOB: begin
            if (last_block) begin
                // Insert End-of-Block marker
                next_state = INSERT_EOB;
                eob_detected = 1'b1;
            end else begin
                next_state = COMPLETE;
            end
        end

        INSERT_EOB: begin
            // EOB code (0x00 with length 4 in simplified table)
            encoded_bits = ac_table[0].code;
            bit_length = ac_table[0].length;
            code_counter = code_counter + 1;
            next_state = FLUSH;
        end

        FLUSH: begin
            // Flush remaining bits
            if (bit_pos > 0) begin
                // Pad with zeros if necessary
                encoded_bits = bit_buffer;
                bit_length = bit_pos;
                bit_pos = 4'b0;
            end
            next_state = COMPLETE;
        end

        COMPLETE: begin
            done = 1'b1;
            next_state = IDLE;
        end

        WAIT: begin
            // Wait state for complex encoding
            next_state = ENCODE_DC;
        end
    endcase
end

endmodule,"module jpeg_huffman_encoder_asserts  (input logic clk,

module ldpc_decoder_min_sum (
    input logic clk,
    input logic rst_n,
    input logic [5:0] llr_input [0:255],      // Log-likelihood ratios from channel
    input logic [7:0] code_length,
    input logic [3:0] iterations_max,
    input logic new_frame,
    output logic [5:0] llr_output [0:255],     // Updated LLRs after decoding
    output logic [0:255] decoded_bits,
    output logic [3:0] iteration_count,
    output logic converged,
    output logic decoding_done
);

typedef enum logic [4:0] {
    IDLE,
    INIT_VARIABLE_NODES,
    CHECK_NODE_UPDATE_0,
    CHECK_NODE_UPDATE_1,
    CHECK_NODE_UPDATE_2,
    CHECK_NODE_UPDATE_3,
    VARIABLE_NODE_UPDATE_0,
    VARIABLE_NODE_UPDATE_1,
    VARIABLE_NODE_UPDATE_2,
    VARIABLE_NODE_UPDATE_3,
    HARD_DECISION,
    PARITY_CHECK,
    EARLY_TERMINATE,
    ITERATION_DONE,
    FINAL_OUTPUT,
    MAX_ITERATIONS,
    DECODE_FAILED
} state_t;

state_t state, next_state;
logic [5:0] var_to_check [0:255][0:7];     // Messages: variable -> check nodes
logic [5:0] check_to_var [0:127][0:15];     // Messages: check -> variable nodes
logic [5:0] current_llr [0:255];
logic [0:255] hard_bits;
logic [7:0] check_node_idx;
logic [7:0] var_node_idx;
logic [7:0] neighbor_idx;
logic [3:0] iter;
logic [15:0] parity_sum;
logic converge_flag;
logic [7:0] check_degree [0:127];            // Degree of check nodes
logic [7:0] var_degree [0:255];               // Degree of variable nodes

// Tanner graph connections (simplified regular LDPC)
parameter CHECK_NODES = 128;
parameter VARIABLE_NODES = 256;
parameter DEGREE_VAR = 4;    // Regular: each variable node connects to 4 check nodes
parameter DEGREE_CHECK = 8;   // Regular: each check node connects to 8 variable nodes

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        iter <= 4'b0;
        check_node_idx <= 8'b0;
        var_node_idx <= 8'b0;
        neighbor_idx <= 8'b0;
        converge_flag <= 1'b0;
        parity_sum <= 16'b0;

        for (int i = 0; i < 256; i++) begin
            current_llr[i] <= 6'b0;
            hard_bits[i] <= 1'b0;
            for (int j = 0; j < 8; j++)
                var_to_check[i][j] <= 6'b0;
        end

        for (int i = 0; i < 128; i++)
            for (int j = 0; j < 16; j++)
                check_to_var[i][j] <= 6'b0;
    end else begin
        state <= next_state;

        // Initialize with channel LLRs
        if (state == INIT_VARIABLE_NODES && new_frame) begin
            for (int i = 0; i < 256; i++)
                current_llr[i] <= llr_input[i];
        end

        // Check node update (Min-Sum algorithm)
        if (state >= CHECK_NODE_UPDATE_0 && state <= CHECK_NODE_UPDATE_3) begin
            logic [5:0] min1, min2;
            logic [5:0] abs_val;
            logic [5:0] product;

            // Find two minimum magnitudes
            min1 = 6'h3F;  // Max value
            min2 = 6'h3F;

            for (int i = 0; i < 8; i++) begin
                abs_val = var_to_check[check_node_idx * 8 + i][neighbor_idx][5] ?
                          -var_to_check[check_node_idx * 8 + i][neighbor_idx] :
                          var_to_check[check_node_idx * 8 + i][neighbor_idx];

                if (abs_val < min1) begin
                    min2 = min1;
                    min1 = abs_val;
                end else if (abs_val < min2) begin
                    min2 = abs_val;
                end
            end

            // Update messages from check node to variable nodes
            for (int i = 0; i < 8; i++) begin
                abs_val = var_to_check[check_node_idx * 8 + i][neighbor_idx][5] ?
                          -var_to_check[check_node_idx * 8 + i][neighbor_idx] :
                          var_to_check[check_node_idx * 8 + i][neighbor_idx];

                product = 1'b1;
                for (int j = 0; j < 8; j++)
                    if (j != i)
                        product = product ^ var_to_check[check_node_idx * 8 + j][neighbor_idx][5];

                if (abs_val == min1)
                    check_to_var[check_node_idx][i] = product ? min2 : -min2;
                else
                    check_to_var[check_node_idx][i] = product ? min1 : -min1;
            end

            check_node_idx <= check_node_idx + 1;
            if (check_node_idx == CHECK_NODES - 1)
                check_node_idx <= 8'b0;
        end

        // Variable node update
        if (state >= VARIABLE_NODE_UPDATE_0 && state <= VARIABLE_NODE_UPDATE_3) begin
            logic [5:0] sum;

            for (int i = 0; i < 4; i++) begin
                sum = current_llr[var_node_idx];
                for (int j = 0; j < 4; j++)
                    if (j != i)
                        sum = sum + check_to_var[var_node_connections[var_node_idx][j]][var_node_idx];

                var_to_check[var_node_idx][i] = sum;
            end

            // Update total LLR
            current_llr[var_node_idx] = current_llr[var_node_idx];
            for (int j = 0; j < 4; j++)
                current_llr[var_node_idx] = current_llr[var_node_idx] +
                                           check_to_var[var_node_connections[var_node_idx][j]][var_node_idx];

            var_node_idx <= var_node_idx + 1;
            if (var_node_idx == VARIABLE_NODES - 1)
                var_node_idx <= 8'b0;
        end

        // Hard decision and parity check
        if (state == HARD_DECISION) begin
            for (int i = 0; i < 256; i++)
                hard_bits[i] <= current_llr[i][5] ? 1'b1 : 1'b0;  // Sign bit
        end

        if (state == PARITY_CHECK) begin
            // Check all parity equations
            converge_flag = 1'b1;
            for (int i = 0; i < CHECK_NODES; i++) begin
                parity_sum = 16'b0;
                for (int j = 0; j < 8; j++)
                    parity_sum = parity_sum ^ hard_bits[i * 8 + j];

                if (parity_sum != 0)
                    converge_flag = 1'b0;
            end

            if (converge_flag)
                iter <= iter + 1;
        end
    end
end

// Variable node to check node connections (simplified regular pattern)
function [7:0] var_node_connections [0:255][0:3];
    for (int i = 0; i < 256; i++)
        for (int j = 0; j < 4; j++)
            var_node_connections[i][j] = (i + j * 64) % 128;
endfunction

always_comb begin
    next_state = state;
    llr_output = current_llr;
    decoded_bits = hard_bits;
    iteration_count = iter;
    converged = converge_flag;
    decoding_done = 1'b0;

    case (state)
        IDLE: begin
            if (new_frame) begin
                next_state = INIT_VARIABLE_NODES;
                iter = 4'b0;
                converge_flag = 1'b0;
            end
        end

        INIT_VARIABLE_NODES: begin
            next_state = CHECK_NODE_UPDATE_0;
            check_node_idx = 8'b0;
        end

        CHECK_NODE_UPDATE_0: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_1;
        end

        CHECK_NODE_UPDATE_1: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_2;
        end

        CHECK_NODE_UPDATE_2: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_3;
        end

        CHECK_NODE_UPDATE_3: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_0;
        end

        VARIABLE_NODE_UPDATE_0: begin
            var_node_idx = 8'b0;
            next_state = VARIABLE_NODE_UPDATE_1;
        end

        VARIABLE_NODE_UPDATE_1: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_2;
            else
                next_state = VARIABLE_NODE_UPDATE_1;
        end

        VARIABLE_NODE_UPDATE_2: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_3;
            else
                next_state = VARIABLE_NODE_UPDATE_2;
        end

        VARIABLE_NODE_UPDATE_3: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = HARD_DECISION;
            else
                next_state = VARIABLE_NODE_UPDATE_0;
        end

        HARD_DECISION: begin
            next_state = PARITY_CHECK;
        end

        PARITY_CHECK: begin
            if (converge_flag) begin
                next_state = EARLY_TERMINATE;
            end else begin
                if (iter < iterations_max - 1)
                    next_state = CHECK_NODE_UPDATE_0;
                else
                    next_state = MAX_ITERATIONS;
            end
        end

        EARLY_TERMINATE: begin
            decoding_done = 1'b1;
            next_state = FINAL_OUTPUT;
        end

        ITERATION_DONE: begin
            iter = iter + 1;
            if (iter < iterations_max)
                next_state = CHECK_NODE_UPDATE_0;
            else
                next_state = MAX_ITERATIONS;
        end

        MAX_ITERATIONS: begin
            decoding_done = 1'b1;
            next_state = FINAL_OUTPUT;
        end

        FINAL_OUTPUT: begin
            decoding_done = 1'b1;
            next_state = IDLE;
        end

        DECODE_FAILED: begin
            decoding_done = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule,"module ldpc_decoder_min_sum_asserts  (input logic clk,

module power_manager_advanced (
    input logic clk,
    input logic rst_n,
    input logic [15:0] activity_level,
    input logic [31:0] time_counter,
    input logic interrupt_req,
    output logic [1:0] power_state,  // 00: FULL, 01: SLEEP, 10: DEEP_SLEEP, 11: OFF
    output logic clock_gated,
    output logic voltage_scaled,
    output logic predictive_wake
);

typedef enum logic [2:0] {
    FULL_PERF,
    MONITOR_ACTIVITY,
    LIGHT_SLEEP,
    DEEP_SLEEP,
    PREDICTIVE_WAKE,
    WAKEUP_SEQ,
    POWER_OFF,
    EMERGENCY_WAKE
} state_t;

state_t state, next_state;
logic [31:0] idle_counter;
logic [15:0] activity_history [0:7];
logic [2:0] history_ptr;
logic [31:0] predicted_wake_time;
logic [3:0] wakeup_countdown;

// Power management parameters
parameter THRESHOLD_LOW = 16'h0100;
parameter THRESHOLD_HIGH = 16'h1000;
parameter IDLE_TIMEOUT = 32'h10000;
parameter DEEP_SLEEP_TIMEOUT = 32'h100000;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= FULL_PERF;
        idle_counter <= 32'b0;
        history_ptr <= 3'b0;
        wakeup_countdown <= 4'b0;
        for (int i = 0; i < 8; i++)
            activity_history[i] <= 16'b0;
    end else begin
        state <= next_state;

        // Update activity history
        if (state != POWER_OFF) begin
            activity_history[history_ptr] <= activity_level;
            history_ptr <= history_ptr + 1;
        end

        // Idle counter logic
        if (state == MONITOR_ACTIVITY && activity_level < THRESHOLD_LOW)
            idle_counter <= idle_counter + 1;
        else
            idle_counter <= 32'b0;

        // Wakeup countdown
        if (state == PREDICTIVE_WAKE)
            wakeup_countdown <= wakeup_countdown - 1;
    end
end

always_comb begin
    next_state = state;
    power_state = 2'b00;
    clock_gated = 1'b0;
    voltage_scaled = 1'b0;
    predictive_wake = 1'b0;

    // Activity prediction logic
    logic [19:0] activity_sum;
    logic [15:0] predicted_activity;
    logic pattern_detected;

    activity_sum = 0;
    for (int i = 0; i < 8; i++)
        activity_sum = activity_sum + activity_history[i];
    predicted_activity = activity_sum >> 3;

    // Detect activity patterns
    pattern_detected = (activity_history[0] > THRESHOLD_HIGH &&
                        activity_history[1] < THRESHOLD_LOW &&
                        activity_history[2] > THRESHOLD_HIGH);

    case (state)
        FULL_PERF: begin
            power_state = 2'b00;
            clock_gated = 1'b0;
            voltage_scaled = 1'b0;

            if (activity_level < THRESHOLD_LOW)
                next_state = MONITOR_ACTIVITY;
        end

        MONITOR_ACTIVITY: begin
            power_state = 2'b00;

            if (activity_level > THRESHOLD_HIGH) begin
                next_state = FULL_PERF;
            end else if (idle_counter > IDLE_TIMEOUT) begin
                next_state = LIGHT_SLEEP;
                clock_gated = 1'b1;  // Immediate clock gating
            end

            // Predictive pattern detection
            if (pattern_detected) begin
                predicted_wake_time = time_counter + 32'h1000;
                next_state = PREDICTIVE_WAKE;
            end
        end

        LIGHT_SLEEP: begin
            power_state = 2'b01;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;  // Scale voltage down

            if (interrupt_req) begin
                next_state = WAKEUP_SEQ;
            end else if (idle_counter > DEEP_SLEEP_TIMEOUT) begin
                next_state = DEEP_SLEEP;
            end

            // Predictive wake from pattern
            if (time_counter >= predicted_wake_time - 32'h100) begin
                next_state = PREDICTIVE_WAKE;
                predictive_wake = 1'b1;
            end
        end

        DEEP_SLEEP: begin
            power_state = 2'b10;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;

            if (interrupt_req) begin
                next_state = EMERGENCY_WAKE;
            end

            // Check if we should power off completely
            if (idle_counter > DEEP_SLEEP_TIMEOUT * 4) begin
                next_state = POWER_OFF;
            end
        end

        PREDICTIVE_WAKE: begin
            power_state = 2'b00;
            clock_gated = 1'b0;
            voltage_scaled = 1'b0;
            predictive_wake = 1'b1;

            wakeup_countdown = 4'd10;
            if (wakeup_countdown == 4'd0) begin
                if (activity_level > THRESHOLD_LOW)
                    next_state = FULL_PERF;
                else
                    next_state = LIGHT_SLEEP;
            end
        end

        WAKEUP_SEQ: begin
            power_state = 2'b00;
            // Stabilization sequence
            voltage_scaled = 1'b0;
            clock_gated = 1'b0;

            if (time_counter[3:0] == 4'b1111)  // Wait for stabilization
                next_state = FULL_PERF;
        end

        EMERGENCY_WAKE: begin
            power_state = 2'b00;
            // Fast wakeup for interrupts
            voltage_scaled = 1'b0;
            clock_gated = 1'b0;
            next_state = FULL_PERF;  // Immediate wake
        end

        POWER_OFF: begin
            power_state = 2'b11;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;

            // Wake on pin change or timer
            if (interrupt_req)
                next_state = EMERGENCY_WAKE;
        end
    endcase
end

endmodule,"module power_manager_advanced_asserts  (input logic clk,

module manchester_encoder_mealy (
    input logic clk,
    input logic rst_n,
    input logic data_in,
    input logic data_valid,
    output logic encoded_out
);

typedef enum logic {WAIT, SEND_0, SEND_1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= WAIT;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    encoded_out = 1'b0;

    case (state)
        WAIT: begin
            if (data_valid) begin
                if (data_in) begin
                    next_state = SEND_1;
                    encoded_out = 1'b1;  // Start with high for '1'
                end else begin
                    next_state = SEND_0;
                    encoded_out = 1'b0;  // Start with low for '0'
                end
            end
        end

        SEND_0: begin
            encoded_out = 1'b1;  // Transition to high in second half
            next_state = WAIT;    // Go back to wait after one bit
        end

        SEND_1: begin
            encoded_out = 1'b0;  // Transition to low in second half
            next_state = WAIT;    // Go back to wait after one bit
        end
    endcase
end

endmodule,"module manchester_encoder_mealy_asserts  (input logic clk,

module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STABLE0;
        counter <= 16'b0;
    end else begin
        state <= next_state;
        if (state == COUNT0 || state == COUNT1)
            counter <= counter + 1;
        else
            counter <= 16'b0;
    end
end

always_comb begin
    next_state = state;
    debounced_out = 1'b0;

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            if (noisy_in)
                next_state = COUNT0;
        end

        COUNT0: begin
            debounced_out = 1'b0;
            if (!noisy_in)
                next_state = STABLE0;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE1;
                debounced_out = 1'b1;  // Output high immediately
            end
        end

        STABLE1: begin
            debounced_out = 1'b1;
            if (!noisy_in)
                next_state = COUNT1;
        end

        COUNT1: begin
            debounced_out = 1'b1;
            if (noisy_in)
                next_state = STABLE1;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE0;
                debounced_out = 1'b0;  // Output low immediately
            end
        end
    endcase
end

endmodule,"module debouncer_mealy_asserts  (input logic clk,

module adaptive_equalizer (
    input logic clk,
    input logic rst_n,
    input logic signed [11:0] rx_signal,      // Received distorted signal
    input logic signed [11:0] training_seq,   // Known training sequence
    input logic training_mode,
    input logic [2:0] convergence_speed,      // 0: slow, 7: fast
    output logic signed [11:0] eq_output,     // Equalized output
    output logic [15:0] snr_estimate,         // Signal-to-noise ratio estimate
    output logic locked
);

typedef enum logic [3:0] {
    RESET,
    ACQUIRE,
    TRAINING,
    COARSE_EQ,
    FINE_EQ,
    TRACKING,
    BLIND_MODE,
    RETRAIN,
    LOCKED_ST,
    UNLOCKED
} state_t;

state_t state, next_state;
logic signed [11:0] delay_line [0:15];  // Tapped delay line
logic signed [15:0] eq_coeffs [0:15];   // Equalizer coefficients (Q4.12)
logic signed [31:0] acc;
logic [3:0] tap_ptr;
logic [15:0] error_power;
logic [15:0] signal_power;
logic [7:0] lock_counter;
logic [3:0] training_index;
logic signed [31:0] error_signal;

// LMS parameters
logic [15:0] mu;  // Step size (Q4.12)
logic [15:0] leakage;  // Coefficient leakage factor

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= RESET;
        tap_ptr <= 4'b0;
        error_power <= 16'b0;
        signal_power <= 16'b0;
        lock_counter <= 8'b0;
        training_index <= 4'b0;

        for (int i = 0; i < 16; i++) begin
            delay_line[i] <= 12'b0;
            eq_coeffs[i] <= 16'b0;
        end
        // Center tap initialization
        eq_coeffs[8] <= 16'h1000;  // 1.0 in Q4.12
    end else begin
        state <= next_state;

        // Shift delay line
        delay_line[0] <= rx_signal;
        for (int i = 1; i < 16; i++)
            delay_line[i] <= delay_line[i-1];

        // Update coefficients based on state
        unique case (state)
            TRAINING, COARSE_EQ, FINE_EQ, TRACKING: begin
                // LMS coefficient update
                for (int i = 0; i < 16; i++) begin
                    if (training_mode) begin
                        // Leaky LMS to prevent coefficient drift
                        eq_coeffs[i] <= eq_coeffs[i] -
                                       ((eq_coeffs[i] * leakage) >>> 12) +
                                       ((error_signal[27:12] * delay_line[i] * mu) >>> 12);
                    end
                end
            end

            BLIND_MODE: begin
                // Constant modulus algorithm (CMA) for blind equalization
                for (int i = 0; i < 16; i++) begin
                    // CMA update: w(n+1) = w(n) + mu * e(n) * x(n) * conj(y(n))
                    // Simplified for BPSK/QPSK
                    eq_coeffs[i] <= eq_coeffs[i] +
                                   ((error_signal[27:12] * delay_line[i] * mu) >>> 12);
                end
            end
        endcase

        // Update power estimates
        signal_power <= signal_power +
                       (rx_signal * rx_signal) - (signal_power >>> 8);
        error_power <= error_power +
                      (error_signal[23:8] * error_signal[23:8]) - (error_power >>> 8);
    end
end

always_comb begin
    next_state = state;
    eq_output = 12'b0;
    snr_estimate = (signal_power * 16'h1000) / (error_power + 1);
    locked = (state == LOCKED_ST);

    // Compute equalizer output
    acc = 32'b0;
    for (int i = 0; i < 16; i++)
        acc = acc + (delay_line[i] * eq_coeffs[i]);
    eq_output = acc[23:12];  // Scale back to 12-bit

    // Error calculation
    if (training_mode)
        error_signal = (training_seq * 16'h1000) - acc;
    else
        error_signal = -acc;  // Decision-directed

    // Lock detection
    logic lock_detect;
    lock_detect = (error_power < (signal_power >>> 4));  // SNR > 12dB

    case (state)
        RESET: begin
            mu = 16'h0800;  // Initial step size
            leakage = 16'h0010;  // Small leakage
            next_state = ACQUIRE;
        end

        ACQUIRE: begin
            // Coarse signal acquisition
            if (signal_power > 16'h1000)
                next_state = TRAINING;
            else if (lock_counter > 100)
                next_state = UNLOCKED;
            else
                lock_counter <= lock_counter + 1;
        end

        TRAINING: begin
            mu = (convergence_speed << 8);  // Scale step size
            training_index <= training_index + 1;

            if (training_index == 4'd15) begin
                if (lock_detect)
                    next_state = COARSE_EQ;
                else
                    next_state = RETRAIN;
            end
        end

        COARSE_EQ: begin
            mu = 16'h0400;  // Medium step size

            if (lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 50)
                    next_state = FINE_EQ;
            end else begin
                lock_counter <= 8'b0;
                if (lock_counter > 200)
                    next_state = RETRAIN;
            end
        end

        FINE_EQ: begin
            mu = 16'h0200;  // Small step size for fine tuning

            if (lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 100)
                    next_state = LOCKED_ST;
            end else begin
                lock_counter <= 8'b0;
                next_state = COARSE_EQ;
            end
        end

        TRACKING: begin
            mu = 16'h0100;  // Very small step size for tracking

            if (!lock_detect && lock_counter > 20)
                next_state = BLIND_MODE;
        end

        BLIND_MODE: begin
            mu = 16'h0200;

            if (lock_detect)
                next_state = TRACKING;
            else if (lock_counter > 500)
                next_state = RETRAIN;
        end

        RETRAIN: begin
            // Reset coefficients
            for (int i = 0; i < 16; i++)
                eq_coeffs[i] = 16'b0;
            eq_coeffs[8] = 16'h1000;
            lock_counter = 8'b0;
            next_state = ACQUIRE;
        end

        LOCKED_ST: begin
            locked = 1'b1;
            mu = 16'h0080;  // Minimum step size

            if (!lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 20)
                    next_state = TRACKING;
            end else begin
                lock_counter <= 8'b0;
            end
        end

        UNLOCKED: begin
            // Signal loss detected
            next_state = ACQUIRE;
        end
    endcase
end

endmodule,"module adaptive_equalizer_asserts  (input logic clk,

module mesi_cache_controller (
    input logic clk,
    input logic rst_n,
    input logic [31:0] address,
    input logic cpu_read,
    input logic cpu_write,
    input logic bus_read,
    input logic bus_write,
    input logic [1:0] snoop_result,  // 00: HIT, 01: HIT_MODIFIED, 10: SHARED
    output logic [1:0] cache_state,   // 00: M, 01: E, 10: S, 11: I
    output logic bus_request,
    output logic cache_hit,
    output logic flush_cache
);

typedef enum logic [1:0] {
    MODIFIED   = 2'b00,
    EXCLUSIVE  = 2'b01,
    SHARED     = 2'b10,
    INVALID    = 2'b11
} mesi_state_t;

mesi_state_t state, next_state;
logic [31:0] tag_memory;
logic [31:0] current_address;
logic pending_bus_op;
logic [1:0] retry_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= INVALID;
        current_address <= 32'b0;
        pending_bus_op <= 1'b0;
        retry_count <= 2'b0;
    end else begin
        state <= next_state;

        // Update address on new access
        if (cpu_read || cpu_write) begin
            current_address <= address;
            pending_bus_op <= 1'b1;
        end

        // Clear pending operation after completion
        if (bus_read || bus_write)
            pending_bus_op <= 1'b0;

        // Retry logic
        if (state == next_state && state != INVALID && pending_bus_op)
            retry_count <= retry_count + 1;
        else
            retry_count <= 2'b0;
    end
end

always_comb begin
    next_state = state;
    cache_state = state;
    bus_request = 1'b0;
    cache_hit = 1'b0;
    flush_cache = 1'b0;

    // Tag comparison (simplified)
    logic tag_match;
    tag_match = (current_address == tag_memory);

    case (state)
        MODIFIED: begin
            cache_hit = 1'b1;

            // Local CPU access
            if (cpu_read || cpu_write) begin
                // Hit in modified state, no bus transaction needed
                next_state = MODIFIED;
            end

            // Snooped bus transactions
            if (bus_read) begin
                // Need to provide data and transition to shared
                next_state = SHARED;
                bus_request = 1'b1;  // Request bus to provide data
                flush_cache = 1'b1;  // Flush modified data
            end

            if (bus_write) begin
                // Another processor wants to write, invalidate
                next_state = INVALID;
                flush_cache = 1'b1;  // Flush before invalidating
            end

            // Snoop result processing
            unique case (snoop_result)
                2'b01: begin  // HIT_MODIFIED on another cache
                    next_state = SHARED;
                    flush_cache = 1'b1;
                end
                2'b10: begin  // SHARED on another cache
                    next_state = SHARED;
                end
            endcase
        end

        EXCLUSIVE: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = EXCLUSIVE;
            end else if (cpu_write) begin
                // Write to exclusive line -> becomes modified
                next_state = MODIFIED;
            end

            if (bus_read) begin
                // Another processor reading -> becomes shared
                next_state = SHARED;
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        SHARED: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = SHARED;
            end else if (cpu_write) begin
                // Write to shared line -> need bus transaction
                next_state = MODIFIED;
                bus_request = 1'b1;  // Request bus for write
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        INVALID: begin
            cache_hit = 1'b0;

            if (cpu_read || cpu_write) begin
                // Miss, need to fetch from memory
                bus_request = 1'b1;

                // Determine next state based on bus response
                if (snoop_result == 2'b10)  // Shared on other cache
                    next_state = SHARED;
                else if (cpu_read)
                    next_state = EXCLUSIVE;
                else if (cpu_write)
                    next_state = MODIFIED;
            end

            // Retry on bus contention
            if (retry_count == 2'b11) begin
                // Force exclusive access after retries
                next_state = EXCLUSIVE;
            end
        end
    endcase

    // Bus arbitration logic
    if (bus_request && (bus_read || bus_write))
        bus_request = 1'b0;  // Clear request when bus is busy
end

endmodule,"module mesi_cache_controller_asserts  (input logic clk,

module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: if (din) begin
            next_state = HIGH;
            rising_edge = 1'b1;  // Output depends on input
        end

        HIGH: if (!din)
            next_state = IDLE;
    endcase
end

endmodule,"module edge_detector_mealy_asserts  (input logic clk,

module mipi_csi2_receiver (
    input logic clk,
    input logic rst_n,

    // MIPI D-PHY interface
    input logic [3:0] data_lane_p [0:3],      // 4 data lanes
    input logic [3:0] data_lane_n [0:3],
    input logic clk_lane_p,
    input logic clk_lane_n,
    input logic lp_mode,                       // Low power mode indicator

    // Protocol decoding
    output logic [15:0] pixel_data [0:3][0:255], // 4 lanes of pixel data
    output logic [7:0] line_length,
    output logic [15:0] frame_width,
    output logic [15:0] frame_height,
    output logic [3:0] data_type,               // RAW8, RAW10, RGB565, YUV422, etc.
    output logic [1:0] virtual_channel,
    output logic frame_start,
    output logic frame_end,
    output logic line_valid,
    output logic data_valid,

    // Error detection
    output logic ecc_error,
    output logic crc_error,
    output logic sync_error,

    // Statistics
    output logic [31:0] frame_count,
    output logic [31:0] line_count,
    output logic [31:0] byte_count
);

typedef enum logic [4:0] {
    IDLE,
    LP_STATE,
    HS_START,
    SYNC_PATTERN,
    ECC_CHECK,
    PH_HEADER,
    PH_DATA_TYPE,
    PH_WORD_COUNT,
    PH_ECC,
    PAYLOAD_DATA,
    CRC_CHECK,
    LINE_END,
    FRAME_START,
    FRAME_END,
    ERROR_RECOVERY,
    WAIT_HS_TRAIL,
    LP_11_STATE
} state_t;

state_t state, next_state;
logic [31:0] word_count;
logic [15:0] pixel_count [0:3];
logic [7:0] lane_data [0:3];
logic [3:0] lane_align;
logic [5:0] ecc_calc;
logic [5:0] ecc_recv;
logic [15:0] crc_calc;
logic [15:0] crc_recv;
logic [31:0] packet_data [0:255];
logic [2:0] lane_index;
logic sync_detected;
logic [7:0] sync_pattern;

// CSI-2 sync codes
parameter SYNC_CODE = 8'hB8;
parameter BLANKING_CODE = 8'h00;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        word_count <= 32'b0;
        lane_index <= 3'b0;
        pixel_count[0] <= 16'b0;
        pixel_count[1] <= 16'b0;
        pixel_count[2] <= 16'b0;
        pixel_count[3] <= 16'b0;
        frame_count <= 32'b0;
        line_count <= 32'b0;
        byte_count <= 32'b0;
        crc_calc <= 16'hFFFF;

        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 256; j++)
                pixel_data[i][j] <= 16'b0;
    end else begin
        state <= next_state;

        case (state)
            HS_START: begin
                // Deserialize lane data
                for (int i = 0; i < 4; i++) begin
                    lane_data[i] <= {data_lane_p[i], data_lane_n[i]};
                end
            end

            SYNC_PATTERN: begin
                sync_pattern <= lane_data[0];
                sync_detected <= (lane_data[0] == SYNC_CODE);
            end

            PH_HEADER: begin
                packet_data[word_count] <= {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                word_count <= word_count + 1;
            end

            PH_DATA_TYPE: begin
                data_type <= lane_data[0][3:0];
                virtual_channel <= lane_data[0][5:4];
            end

            PH_WORD_COUNT: begin
                word_count <= {lane_data[1], lane_data[0]};
            end

            PH_ECC: begin
                // Calculate ECC (simplified Hamming code)
                ecc_calc <= 6'b0;
                for (int i = 0; i < 24; i++) begin
                    // ECC calculation logic
                end
                ecc_recv <= lane_data[0][5:0];

                if (ecc_calc != ecc_recv)
                    ecc_error <= 1'b1;
            end

            PAYLOAD_DATA: begin
                if (word_count > 0) begin
                    // Distribute data across lanes
                    for (int lane = 0; lane < 4; lane++) begin
                        case (data_type)
                            4'b0010: begin  // RAW10
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], 2'b0};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end

                            4'b0111: begin  // RGB565
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane*2 +: 16]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                                lane_index <= lane_index + 1;
                            end

                            4'b1010: begin  // YUV422 8-bit
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], lane_data[lane][7:0]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end
                        endcase
                    end

                    word_count <= word_count - 1;
                    byte_count <= byte_count + 4;

                    // Update CRC
                    crc_calc <= crc_calc ^ {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                end
            end

            CRC_CHECK: begin
                crc_recv <= {lane_data[1], lane_data[0]};
                if (crc_calc != crc_recv)
                    crc_error <= 1'b1;
            end

            LINE_END: begin
                line_valid <= 1'b1;
                line_length <= pixel_count[0][7:0];
                line_count <= line_count + 1;

                for (int i = 0; i < 4; i++)
                    pixel_count[i] <= 16'b0;
            end

            FRAME_START: begin
                frame_start <= 1'b1;
                frame_count <= frame_count + 1;
                line_count <= 32'b0;
            end

            FRAME_END: begin
                frame_end <= 1'b1;
                frame_height <= line_count[15:0];
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    data_valid = (state == PAYLOAD_DATA);

    case (state)
        IDLE: begin
            if (!lp_mode) begin
                next_state = LP_STATE;
            end
        end

        LP_STATE: begin
            if (clk_lane_p && !clk_lane_n)  // Clock rising
                next_state = HS_START;
        end

        HS_START: begin
            next_state = SYNC_PATTERN;
        end

        SYNC_PATTERN: begin
            if (sync_detected) begin
                next_state = PH_HEADER;
            end else if (lane_data[0] == BLANKING_CODE) begin
                next_state = LINE_END;
            end else begin
                sync_error <= 1'b1;
                next_state = ERROR_RECOVERY;
            end
        end

        PH_HEADER: begin
            next_state = PH_DATA_TYPE;
        end

        PH_DATA_TYPE: begin
            next_state = PH_WORD_COUNT;
        end

        PH_WORD_COUNT: begin
            next_state = PH_ECC;
        end

        PH_ECC: begin
            if (ecc_error)
                next_state = ERROR_RECOVERY;
            else begin
                case (data_type)
                    4'b0000: next_state = FRAME_START;  // Frame start code
                    4'b0001: next_state = FRAME_END;    // Frame end code
                    4'b0010, 4'b0111, 4'b1010: next_state = PAYLOAD_DATA;
                    default: next_state = WAIT_HS_TRAIL;
                endcase
            end
        end

        PAYLOAD_DATA: begin
            if (word_count == 0)
                next_state = CRC_CHECK;
        end

        CRC_CHECK: begin
            next_state = WAIT_HS_TRAIL;
        end

        LINE_END: begin
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_START: begin
            frame_start <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_END: begin
            frame_end <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        WAIT_HS_TRAIL: begin
            if (lp_mode)
                next_state = LP_11_STATE;
        end

        LP_11_STATE: begin
            if (!lp_mode)
                next_state = HS_START;
            else
                next_state = IDLE;
        end

        ERROR_RECOVERY: begin
            if (lp_mode)
                next_state = IDLE;
        end
    endcase
end

endmodule,"module mipi_csi2_receiver_asserts  (input logic clk,

module pcie_tlp_processor (
    input logic clk,
    input logic rst_n,
    input logic [63:0] tlp_header [0:3],     // 4 DW TLP header
    input logic [31:0] payload_data [0:255], // Payload data
    input logic [7:0] payload_length,
    input logic tlp_valid,
    input logic [11:0] credits_available,     // Flow control credits
    input logic [2:0] traffic_class,
    output logic [63:0] processed_header [0:3],
    output logic tlp_forward,
    output logic [1:0] tlp_type,               // 00:MRd,01:MWr,10:Cpl,11:CplD
    output logic [9:0] requester_id,
    output logic [7:0] tag,
    output logic [3:0] first_be,               // First DW byte enable
    output logic [3:0] last_be,                // Last DW byte enable
    output logic credit_consumed,
    output logic [11:0] credits_remaining
);

typedef enum logic [3:0] {
    IDLE,
    PARSE_HEADER,
    CHECK_CREDITS,
    MEMORY_READ,
    MEMORY_WRITE,
    COMPLETION,
    COMPLETION_DATA,
    CHECK_ADDRESS_ALIGN,
    PROCESS_PAYLOAD,
    UPDATE_CREDITS,
    FORWARD_PACKET,
    REJECT_PACKET,
    WAIT_CREDITS
} state_t;

state_t state, next_state;
logic [63:0] header [0:3];
logic [31:0] address;
logic [9:0] req_id;
logic [7:0] packet_tag;
logic [6:0] dw_count;
logic [11:0] required_credits;
logic [1:0] fmt_type;
logic [4:0] tlp_length;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        for (int i = 0; i < 4; i++)
            header[i] <= 64'b0;
        req_id <= 10'b0;
        packet_tag <= 8'b0;
        dw_count <= 7'b0;
        required_credits <= 12'b0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (tlp_valid) begin
                    for (int i = 0; i < 4; i++)
                        header[i] <= tlp_header[i];
                end
            end

            PARSE_HEADER: begin
                // Parse TLP header fields
                fmt_type <= header[0][63:56];  // Fmt and Type fields
                tlp_length <= header[0][54:48]; // Length field (in DW)
                req_id <= header[1][31:22];     // Requester ID
                packet_tag <= header[1][21:16];  // Tag

                // Calculate required credits (1 credit = 4 DW)
                required_credits <= (tlp_length + 3) >> 2;
            end

            PROCESS_PAYLOAD: begin
                if (dw_count < tlp_length) begin
                    // Process payload data
                    dw_count <= dw_count + 1;
                end
            end

            UPDATE_CREDITS: begin
                credits_remaining <= credits_available - required_credits;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    tlp_forward = 1'b0;
    credit_consumed = 1'b0;
    credits_remaining = credits_available;
    processed_header = header;
    tlp_type = 2'b00;
    requester_id = req_id;
    tag = packet_tag;

    case (state)
        IDLE: begin
            if (tlp_valid) begin
                next_state = PARSE_HEADER;
            end
        end

        PARSE_HEADER: begin
            case (fmt_type[6:5])  // Fmt field
                2'b00: begin  // 3 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b01: begin  // 4 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b10: begin  // 3 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
                2'b11: begin  // 4 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
            endcase
        end

        CHECK_CREDITS: begin
            if (required_credits <= credits_available) begin
                case (fmt_type[4:0])  // Type field
                    5'b00000: begin  // Memory Read
                        next_state = MEMORY_READ;
                    end
                    5'b00001: begin  // Memory Write
                        next_state = MEMORY_WRITE;
                    end
                    5'b01010: begin  // Completion
                        next_state = COMPLETION;
                    end
                    5'b01011: begin  // Completion with Data
                        next_state = COMPLETION_DATA;
                    end
                    default: begin
                        next_state = REJECT_PACKET;
                    end
                endcase
            end else begin
                next_state = WAIT_CREDITS;
            end
        end

        MEMORY_READ: begin
            tlp_type = 2'b00;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = UPDATE_CREDITS;
        end

        MEMORY_WRITE: begin
            tlp_type = 2'b01;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = PROCESS_PAYLOAD;
        end

        COMPLETION: begin
            tlp_type = 2'b10;
            next_state = UPDATE_CREDITS;
        end

        COMPLETION_DATA: begin
            tlp_type = 2'b11;
            next_state = PROCESS_PAYLOAD;
        end

        PROCESS_PAYLOAD: begin
            if (dw_count >= tlp_length - 1) begin
                case (tlp_type)
                    2'b00, 2'b10: next_state = UPDATE_CREDITS;
                    2'b01, 2'b11: next_state = FORWARD_PACKET;
                endcase
            end
        end

        UPDATE_CREDITS: begin
            credit_consumed = 1'b1;
            next_state = FORWARD_PACKET;
        end

        FORWARD_PACKET: begin
            tlp_forward = 1'b1;
            next_state = IDLE;
        end

        WAIT_CREDITS: begin
            // Wait for credits to become available
            if (required_credits <= credits_available)
                next_state = MEMORY_READ;
        end

        REJECT_PACKET: begin
            // Reject unsupported TLP types
            next_state = IDLE;
        end
    endcase
end

endmodule,"module pcie_tlp_processor_asserts  (input logic clk,

module ddr4_controller (
    input logic clk,
    input logic rst_n,
    input logic [31:0] address,
    input logic [7:0] burst_length,
    input logic read_request,
    input logic write_request,
    input logic [511:0] write_data,
    output logic [511:0] read_data,
    output logic read_valid,
    output logic write_done,
    output logic ready,

    // DDR4 physical interface
    output logic [16:0] ddr_addr,
    output logic [2:0] ddr_bank,
    output logic ddr_ras_n,
    output logic ddr_cas_n,
    output logic ddr_we_n,
    output logic ddr_cke,
    output logic ddr_cs_n,
    output logic [1:0] ddr_bg,  // Bank group
    output logic ddr_act_n,      // Activate
    output logic [3:0] ddr_dm,   // Data mask
    inout logic [31:0] ddr_dq    // Data bus
);

typedef enum logic [5:0] {
    IDLE,
    PRECHARGE_ALL,
    PRECHARGE_BANK,
    ACTIVATE_ROW,
    READ_BURST,
    WRITE_BURST,
    READ_PRECHARGE,
    WRITE_PRECHARGE,
    AUTO_REFRESH,
    REFRESH_WAIT,
    ZQ_CALIBRATION,
    POWER_DOWN_ENTRY,
    POWER_DOWN_EXIT,
    SELF_REFRESH,
    SELF_REFRESH_EXIT,
    MODE_REG_WRITE,
    MODE_REG_READ,
    WAIT_TRCD,           // RAS to CAS delay
    WAIT_TRP,            // Precharge to activate delay
    WAIT_TRAS,           // Active to precharge delay
    WAIT_TRC,            // Active to active delay
    WAIT_TRFC,           // Refresh cycle time
    WAIT_TWR,            // Write recovery time
    WAIT_TWTR,           // Write to read delay
    WAIT_TCCD,           // CAS to CAS delay
    BANK_CONFLICT,
    ROW_CONFLICT,
    SCHEDULE_REFRESH
} state_t;

state_t state, next_state;
logic [15:0] row_address [0:3][0:7];  // Row address per bank group and bank
logic [2:0] active_bank [0:3];        // Currently active bank per bank group
logic [15:0] active_row [0:3];         // Currently active row per bank group
logic bank_active [0:3][0:7];          // Bank active flag
logic [31:0] refresh_timer;
logic [7:0] timing_counter;
logic [1:0] current_bg;
logic [2:0] current_bank;
logic [15:0] current_row;
logic [2:0] col_address;
logic refresh_request;
logic [1:0] bg_decode;
logic [2:0] bank_decode;

// Address decoding
assign bg_decode = address[17:16];      // Bank group
assign bank_decode = address[15:13];     // Bank
assign current_row = address[31:18];      // Row address
assign col_address = address[12:10];      // Column address

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        refresh_timer <= 32'b0;
        timing_counter <= 8'b0;

        for (int bg = 0; bg < 4; bg++) begin
            active_bank[bg] <= 3'b0;
            active_row[bg] <= 16'b0;
            for (int bank = 0; bank < 8; bank++) begin
                bank_active[bg][bank] <= 1'b0;
                row_address[bg][bank] <= 16'b0;
            end
        end
    end else begin
        state <= next_state;

        case (state)
            ACTIVATE_ROW: begin
                row_address[current_bg][current_bank] <= current_row;
                active_row[current_bg] <= current_row;
                active_bank[current_bg] <= current_bank;
                bank_active[current_bg][current_bank] <= 1'b1;
            end

            PRECHARGE_BANK: begin
                bank_active[current_bg][current_bank] <= 1'b0;
            end

            PRECHARGE_ALL: begin
                for (int bg = 0; bg < 4; bg++)
                    for (int bank = 0; bank < 8; bank++)
                        bank_active[bg][bank] <= 1'b0;
            end

            WAIT_TRCD, WAIT_TRP, WAIT_TRAS, WAIT_TRC,
            WAIT_TRFC, WAIT_TWR, WAIT_TWTR, WAIT_TCCD: begin
                timing_counter <= timing_counter + 1;
            end

            AUTO_REFRESH: begin
                refresh_timer <= 32'b0;
            end

            default: begin
                refresh_timer <= refresh_timer + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    ready = (state == IDLE);
    read_valid = 1'b0;
    write_done = 1'b0;
    ddr_cke = 1'b1;
    ddr_cs_n = 1'b0;
    ddr_act_n = 1'b1;
    ddr_ras_n = 1'b1;
    ddr_cas_n = 1'b1;
    ddr_we_n = 1'b1;
    ddr_bg = current_bg;
    ddr_bank = current_bank;
    ddr_addr = {1'b0, current_row};  // Row/Column address

    // Decode current access
    current_bg = bg_decode;
    current_bank = bank_decode;

    // Refresh request every 7.8us (at 400MHz, ~3120 cycles)
    refresh_request = (refresh_timer > 3120);

    case (state)
        IDLE: begin
            if (refresh_request) begin
                next_state = SCHEDULE_REFRESH;
            end else if (read_request || write_request) begin
                // Check if target bank is active
                if (bank_active[current_bg][current_bank]) begin
                    if (row_address[current_bg][current_bank] == current_row) begin
                        // Row already active
                        if (read_request)
                            next_state = READ_BURST;
                        else
                            next_state = WRITE_BURST;
                    end else begin
                        // Row conflict
                        next_state = ROW_CONFLICT;
                    end
                end else begin
                    // Bank not active
                    next_state = ACTIVATE_ROW;
                end
            end
        end

        ACTIVATE_ROW: begin
            ddr_act_n = 1'b0;
            ddr_addr = {1'b0, current_row};
            next_state = WAIT_TRCD;
        end

        WAIT_TRCD: begin
            // tRCD = 12-15 cycles
            if (timing_counter >= 12) begin
                if (read_request)
                    next_state = READ_BURST;
                else
                    next_state = WRITE_BURST;
            end
        end

        READ_BURST: begin
            ddr_ras_n = 1'b1;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b1;
            ddr_addr = {3'b0, col_address, 4'b0};

            if (burst_length == 8) begin
                next_state = READ_PRECHARGE;
            end
        end

        WRITE_BURST: begin
            ddr_ras_n = 1'b1;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b0;
            ddr_addr = {3'b0, col_address, 4'b0};
            ddr_dq = write_data[31:0];  // Write first 32 bits

            if (burst_length == 8) begin
                next_state = WRITE_PRECHARGE;
            end
        end

        READ_PRECHARGE: begin
            // Auto precharge after read
            next_state = PRECHARGE_BANK;
        end

        WRITE_PRECHARGE: begin
            // Need write recovery time
            next_state = WAIT_TWR;
        end

        WAIT_TWR: begin
            // tWR = 12 cycles
            if (timing_counter >= 12)
                next_state = PRECHARGE_BANK;
        end

        PRECHARGE_BANK: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b1;
            ddr_we_n = 1'b0;
            ddr_addr[10] = 1'b0;  // Single bank precharge
            next_state = WAIT_TRP;
        end

        WAIT_TRP: begin
            // tRP = 12 cycles
            if (timing_counter >= 12) begin
                if (read_request)
                    read_valid = 1'b1;
                else
                    write_done = 1'b1;
                next_state = IDLE;
            end
        end

        ROW_CONFLICT: begin
            next_state = PRECHARGE_BANK;
        end

        BANK_CONFLICT: begin
            // Need to precharge other bank in same bank group
            next_state = PRECHARGE_BANK;
        end

        SCHEDULE_REFRESH: begin
            if (!bank_active[current_bg][current_bank]) begin
                next_state = AUTO_REFRESH;
            end else begin
                // Need to precharge active banks first
                next_state = PRECHARGE_ALL;
            end
        end

        PRECHARGE_ALL: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b1;
            ddr_we_n = 1'b0;
            ddr_addr[10] = 1'b1;  // All banks precharge
            next_state = WAIT_TRP;
        end

        AUTO_REFRESH: begin
            ddr_ras_n = 1'b0;
            ddr_cas_n = 1'b0;
            ddr_we_n = 1'b1;
            next_state = REFRESH_WAIT;
        end

        REFRESH_WAIT: begin
            // tRFC = 160-350 cycles depending on density
            if (timing_counter >= 160)
                next_state = IDLE;
        end

        ZQ_CALIBRATION: begin
            // ZQ calibration sequence
            next_state = IDLE;
        end

        MODE_REG_WRITE: begin
            // Load mode register
            next_state = IDLE;
        end

        MODE_REG_READ: begin
            // Read mode register
            next_state = IDLE;
        end
    endcase
end

endmodule,"module ddr4_controller_asserts  (input logic clk,

module image_signal_processor (
    input logic clk,
    input logic rst_n,

    // Bayer pattern input (RAW sensor data)
    input logic [9:0] bayer_pixel,
    input logic [15:0] frame_width,
    input logic [15:0] frame_height,
    input logic hsync,
    input logic vsync,
    input logic pixel_valid,

    // Configuration registers
    input logic [15:0] white_balance_r,
    input logic [15:0] white_balance_g,
    input logic [15:0] white_balance_b,
    input logic [7:0] gamma_lut [0:255],
    input logic [2:0] bayer_pattern,  // 0: RGGB, 1: GRBG, 2: GBRG, 3: BGGR

    // RGB output (24-bit)
    output logic [7:0] rgb_r,
    output logic [7:0] rgb_g,
    output logic [7:0] rgb_b,
    output logic rgb_valid,
    output logic frame_sync,
    output logic line_sync
);

//-------------------------------------------------------------------------
// Pipeline Stage 1: Bayer Demosaic
//-------------------------------------------------------------------------
typedef struct {
    logic [9:0] pixels [0:2][0:2];  // 3x3 window
    logic [15:0] x_count;
    logic [15:0] y_count;
    logic hsync_d1;
    logic vsync_d1;
    logic valid_d1;
} stage1_t;

stage1_t stage1_reg, stage1_next;
logic [9:0] line_buffer [0:2047][0:1];  // 2-line buffer for 3x3 window

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1_reg.x_count <= 16'b0;
        stage1_reg.y_count <= 16'b0;
        stage1_reg.hsync_d1 <= 1'b0;
        stage1_reg.vsync_d1 <= 1'b0;
        stage1_reg.valid_d1 <= 1'b0;

        for (int i = 0; i < 2048; i++)
            for (int j = 0; j < 2; j++)
                line_buffer[i][j] <= 10'b0;
    end else begin
        stage1_reg <= stage1_next;

        // Update line buffer
        if (pixel_valid) begin
            line_buffer[stage1_reg.x_count][0] <= bayer_pixel;
            line_buffer[stage1_reg.x_count][1] <= line_buffer[stage1_reg.x_count][0];
        end
    end
end

always_comb begin
    stage1_next = stage1_reg;
    stage1_next.hsync_d1 = hsync;
    stage1_next.vsync_d1 = vsync;
    stage1_next.valid_d1 = pixel_valid;

    if (pixel_valid) begin
        stage1_next.x_count = stage1_reg.x_count + 1;

        // Update 3x3 window
        stage1_next.pixels[0][0] = stage1_reg.pixels[0][1];
        stage1_next.pixels[0][1] = stage1_reg.pixels[0][2];
        stage1_next.pixels[0][2] = line_buffer[stage1_reg.x_count][1];

        stage1_next.pixels[1][0] = stage1_reg.pixels[1][1];
        stage1_next.pixels[1][1] = stage1_reg.pixels[1][2];
        stage1_next.pixels[1][2] = line_buffer[stage1_reg.x_count][0];

        stage1_next.pixels[2][0] = stage1_reg.pixels[2][1];
        stage1_next.pixels[2][1] = stage1_reg.pixels[2][2];
        stage1_next.pixels[2][2] = bayer_pixel;

        if (stage1_reg.x_count == frame_width - 1) begin
            stage1_next.x_count = 16'b0;
            stage1_next.y_count = stage1_reg.y_count + 1;
        end
    end
end

//-------------------------------------------------------------------------
// Stage 1 Output: Demosaic Interpolation
//-------------------------------------------------------------------------
logic [15:0] r_interp, g_interp, b_interp;
logic stage1_valid;

always_comb begin
    stage1_valid = stage1_reg.valid_d1 &&
                   stage1_reg.x_count > 0 &&
                   stage1_reg.x_count < frame_width - 1 &&
                   stage1_reg.y_count > 0 &&
                   stage1_reg.y_count < frame_height - 1;

    if (stage1_valid) begin
        case (bayer_pattern)
            3'b000: begin  // RGGB
                r_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b001: begin  // GRBG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                r_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b010: begin  // GBRG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                b_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end

            3'b011: begin  // BGGR
                b_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end
        endcase
    end else begin
        r_interp = 16'b0;
        g_interp = 16'b0;
        b_interp = 16'b0;
    end
end

//-------------------------------------------------------------------------
// Pipeline Stage 2: White Balance
//-------------------------------------------------------------------------
typedef struct {
    logic [23:0] rgb_data;  // 8-bit per channel after white balance
    logic hsync_d2;
    logic vsync_d2;
    logic valid_d2;
} stage2_t;

stage2_t stage2_reg, stage2_next;
logic [23:0] wb_r, wb_g, wb_b;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage2_reg.valid_d2 <= 1'b0;
        stage2_reg.hsync_d2 <= 1'b0;
        stage2_reg.vsync_d2 <= 1'b0;
        stage2_reg.rgb_data <= 24'b0;
    end else begin
        stage2_reg <= stage2_next;
    end
end

always_comb begin
    stage2_next = stage2_reg;
    stage2_next.hsync_d2 = stage1_reg.hsync_d1;
    stage2_next.vsync_d2 = stage1_reg.vsync_d1;
    stage2_next.valid_d2 = stage1_valid;

    // Apply white balance gains
    wb_r = (r_interp * white_balance_r) >> 8;
    wb_g = (g_interp * white_balance_g) >> 8;
    wb_b = (b_interp * white_balance_b) >> 8;

    // Clip to 8-bit
    stage2_next.rgb_data[23:16] = (wb_r[15:0] > 16'hFF00) ? 8'hFF : wb_r[15:8];
    stage2_next.rgb_data[15:8]  = (wb_g[15:0] > 16'hFF00) ? 8'hFF : wb_g[15:8];
    stage2_next.rgb_data[7:0]   = (wb_b[15:0] > 16'hFF00) ? 8'hFF : wb_b[15:8];
end

//-------------------------------------------------------------------------
// Pipeline Stage 3: Gamma Correction
//-------------------------------------------------------------------------
typedef struct {
    logic [7:0] r_gamma;
    logic [7:0] g_gamma;
    logic [7:0] b_gamma;
    logic hsync_d3;
    logic vsync_d3;
    logic valid_d3;
} stage3_t;

stage3_t stage3_reg, stage3_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage3_reg.valid_d3 <= 1'b0;
        stage3_reg.hsync_d3 <= 1'b0;
        stage3_reg.vsync_d3 <= 1'b0;
        stage3_reg.r_gamma <= 8'b0;
        stage3_reg.g_gamma <= 8'b0;
        stage3_reg.b_gamma <= 8'b0;
    end else begin
        stage3_reg <= stage3_next;
    end
end

always_comb begin
    stage3_next = stage3_reg;
    stage3_next.hsync_d3 = stage2_reg.hsync_d2;
    stage3_next.vsync_d3 = stage2_reg.vsync_d2;
    stage3_next.valid_d3 = stage2_reg.valid_d2;

    // Apply gamma correction using LUT
    stage3_next.r_gamma = gamma_lut[stage2_reg.rgb_data[23:16]];
    stage3_next.g_gamma = gamma_lut[stage2_reg.rgb_data[15:8]];
    stage3_next.b_gamma = gamma_lut[stage2_reg.rgb_data[7:0]];
end

//-------------------------------------------------------------------------
// Output Stage
//-------------------------------------------------------------------------
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rgb_r <= 8'b0;
        rgb_g <= 8'b0;
        rgb_b <= 8'b0;
        rgb_valid <= 1'b0;
        frame_sync <= 1'b0;
        line_sync <= 1'b0;
    end else begin
        rgb_r <= stage3_reg.r_gamma;
        rgb_g <= stage3_reg.g_gamma;
        rgb_b <= stage3_reg.b_gamma;
        rgb_valid <= stage3_reg.valid_d3;
        frame_sync <= stage3_reg.vsync_d3;
        line_sync <= stage3_reg.hsync_d3;
    end
end

endmodule,"module image_signal_processor_asserts  (input logic clk,

module ethernet_crc32_pipelined (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_in,
    input logic data_valid,
    input logic start_frame,
    input logic end_frame,
    output logic [31:0] crc_out,
    output logic crc_valid,
    output logic crc_error
);

//-------------------------------------------------------------------------
// State enumeration
//-------------------------------------------------------------------------
typedef enum logic [1:0] {
    IDLE,
    CALC,
    FINALIZE,
    CHECK
} state_t;

//-------------------------------------------------------------------------
// CRC32 Constants (Ethernet polynomial: 0x04C11DB7)
//-------------------------------------------------------------------------
parameter CRC32_POLY = 32'h04C11DB7;
parameter CRC32_INIT = 32'hFFFFFFFF;
parameter CRC32_RESIDUE = 32'hDEBB20E3;

//-------------------------------------------------------------------------
// Sequential logic: State and pipeline registers
//-------------------------------------------------------------------------
state_t state_reg, state_next;
logic [31:0] crc_reg, crc_next;
logic [31:0] crc_pipe1, crc_pipe2;
logic [7:0] data_pipe1, data_pipe2;
logic valid_pipe1, valid_pipe2;
logic start_pipe1, start_pipe2;
logic end_pipe1, end_pipe2;
logic [2:0] byte_count_reg, byte_count_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= IDLE;
        crc_reg <= CRC32_INIT;
        crc_pipe1 <= 32'b0;
        crc_pipe2 <= 32'b0;
        data_pipe1 <= 8'b0;
        data_pipe2 <= 8'b0;
        valid_pipe1 <= 1'b0;
        valid_pipe2 <= 1'b0;
        start_pipe1 <= 1'b0;
        start_pipe2 <= 1'b0;
        end_pipe1 <= 1'b0;
        end_pipe2 <= 1'b0;
        byte_count_reg <= 3'b0;
    end else begin
        state_reg <= state_next;
        crc_reg <= crc_next;
        byte_count_reg <= byte_count_next;

        // Pipeline stage 1
        crc_pipe1 <= crc_reg;
        data_pipe1 <= data_in;
        valid_pipe1 <= data_valid;
        start_pipe1 <= start_frame;
        end_pipe1 <= end_frame;

        // Pipeline stage 2
        crc_pipe2 <= crc_pipe1;
        data_pipe2 <= data_pipe1;
        valid_pipe2 <= valid_pipe1;
        start_pipe2 <= start_pipe1;
        end_pipe2 <= end_pipe1;
    end
end

//-------------------------------------------------------------------------
// CRC32 calculation function (combinational)
//-------------------------------------------------------------------------
function automatic [31:0] crc32_byte;
    input [31:0] crc;
    input [7:0] data;
    logic [31:0] new_crc;
    logic [31:0] poly;
begin
    new_crc = crc ^ {24'b0, data};
    poly = CRC32_POLY;

    for (int i = 0; i < 8; i++) begin
        if (new_crc[0])
            new_crc = (new_crc >> 1) ^ poly;
        else
            new_crc = (new_crc >> 1);
    end

    crc32_byte = new_crc;
end
endfunction

//-------------------------------------------------------------------------
// Pipeline stage 1 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage1_out;
logic [31:0] crc_stage1_init;
logic stage1_valid;

always_comb begin
    // Stage 1 CRC calculation
    if (start_pipe1)
        crc_stage1_init = CRC32_INIT;
    else
        crc_stage1_init = crc_pipe1;

    if (valid_pipe1)
        crc_stage1_out = crc32_byte(crc_stage1_init, data_in);
    else
        crc_stage1_out = crc_stage1_init;

    stage1_valid = valid_pipe1;
end

//-------------------------------------------------------------------------
// Pipeline stage 2 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage2_out;
logic [31:0] crc_stage2_final;
logic stage2_start, stage2_end;

always_comb begin
    // Stage 2 CRC calculation
    if (start_pipe2)
        crc_stage2_out = crc32_byte(CRC32_INIT, data_pipe2);
    else if (valid_pipe2)
        crc_stage2_out = crc32_byte(crc_pipe2, data_pipe2);
    else
        crc_stage2_out = crc_pipe2;

    // Final XOR
    crc_stage2_final = ~crc_stage2_out;

    stage2_start = start_pipe2;
    stage2_end = end_pipe2;
end

//-------------------------------------------------------------------------
// Main FSM combinational logic
//-------------------------------------------------------------------------
always_comb begin
    state_next = state_reg;
    crc_next = crc_reg;
    byte_count_next = byte_count_reg;
    crc_out = 32'b0;
    crc_valid = 1'b0;
    crc_error = 1'b0;

    case (state_reg)
        IDLE: begin
            if (start_frame) begin
                state_next = CALC;
                crc_next = CRC32_INIT;
                byte_count_next = 3'b0;
            end
        end

        CALC: begin
            // Update CRC with pipelined output
            crc_next = crc_stage2_out;

            if (valid_pipe2)
                byte_count_next = byte_count_reg + 1;

            if (end_pipe2) begin
                state_next = FINALIZE;
                crc_next = crc_stage2_final;
            end
        end

        FINALIZE: begin
            crc_out = crc_reg;
            crc_valid = 1'b1;
            state_next = CHECK;
        end

        CHECK: begin
            // Check against expected residue
            if (crc_reg == CRC32_RESIDUE)
                crc_error = 1'b0;
            else
                crc_error = 1'b1;

            if (!data_valid)
                state_next = IDLE;
        end
    endcase
end

endmodule,"module ethernet_crc32_pipelined_asserts  (input logic clk,

module usb3_protocol_layer (
    input logic clk,
    input logic rst_n,
    input logic [31:0] packet_data [0:15],   // Packet data (max 16 DW)
    input logic [4:0] packet_length,
    input logic packet_valid,
    input logic [3:0] endpoint,
    input logic [2:0] device_address,
    input logic direction,                     // 0: OUT, 1: IN
    input logic setup_stage,

    // Link Management
    input logic [1:0] link_status,             // From PHY
    input logic link_up,
    output logic [1:0] link_command,

    // Protocol outputs
    output logic [31:0] rx_data [0:15],
    output logic [4:0] rx_length,
    output logic rx_valid,
    output logic [3:0] rx_endpoint,
    output logic [2:0] rx_device,
    output logic [1:0] transaction_type,       // 00:SETUP,01:DATA,10:STATUS,11:PING
    output logic [2:0] sequence_number,
    output logic data_xfer_complete,
    output logic link_power_state               // 0:L0,1:L1,2:L2
);

typedef enum logic [5:0] {
    // Link states
    LINK_RESET,
    LINK_POLLING,
    LINK_U0,              // Active
    LINK_U1,              // Sleep
    LINK_U2,              // Deep sleep
    LINK_U3,              // Suspend
    LINK_RECOVERY,
    LINK_HOT_RESET,

    // Protocol states
    PROTOCOL_IDLE,
    PROTOCOL_SETUP,
    PROTOCOL_DATA_OUT,
    PROTOCOL_DATA_IN,
    PROTOCOL_STATUS,
    PROTOCOL_PING,
    PROTOCOL_NYET,
    PROTOCOL_ERDY,

    // Packet handling
    PACKET_HEADER,
    PACKET_DATA,
    PACKET_CRC,
    PACKET_ACK,
    PACKET_NACK,
    PACKET_STALL,
    PACKET_NOTIFY,

    // Flow control
    FLOW_CREDIT_UPDATE,
    FLOW_WAIT,
    FLOW_TIMEOUT,

    // Error handling
    ERROR_RETRY,
    ERROR_RECOVERY,
    ERROR_TIMEOUT
} state_t;

state_t link_state, protocol_state, next_state;
logic [2:0] seq_num;
logic [3:0] credit_count [0:15];  // Credits per endpoint
logic [15:0] retry_counter;
logic [31:0] timeout_counter;
logic [4:0] data_phase;
logic burst_mode;
logic [2:0] retry_count;

// Packet type encoding
typedef enum logic [4:0] {
    PTYPE_SETUP     = 5'b00001,
    PTYPE_DATA      = 5'b00010,
    PTYPE_ACK       = 5'b00100,
    PTYPE_NACK      = 5'b01000,
    PTYPE_STALL     = 5'b10000,
    PTYPE_ERDY      = 5'b11000,
    PTYPE_PING      = 5'b10100,
    PTYPE_NOTIFY    = 5'b10010
} packet_type_t;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        link_state <= LINK_RESET;
        protocol_state <= PROTOCOL_IDLE;
        seq_num <= 3'b0;
        data_phase <= 5'b0;
        retry_count <= 3'b0;
        retry_counter <= 16'b0;
        timeout_counter <= 32'b0;

        for (int i = 0; i < 16; i++)
            credit_count[i] <= 4'b1111;  // Initial credits
    end else begin
        link_state <= next_state;
        protocol_state <= next_state;

        case (link_state)
            LINK_U0: begin
                // Update sequence number
                case (protocol_state)
                    PACKET_ACK: seq_num <= seq_num + 1;
                    PACKET_NACK: retry_count <= retry_count + 1;
                endcase
            end

            LINK_U1, LINK_U2: begin
                // Power saving states
                if (timeout_counter < 32'hFFFFFFFF)
                    timeout_counter <= timeout_counter + 1;
            end

            LINK_RECOVERY: begin
                retry_counter <= retry_counter + 1;
            end
        endcase

        case (protocol_state)
            FLOW_CREDIT_UPDATE: begin
                credit_count[endpoint] <= credit_count[endpoint] - 1;
            end

            ERROR_TIMEOUT: begin
                timeout_counter <= timeout_counter + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = protocol_state;
    link_command = 2'b00;
    rx_valid = 1'b0;
    data_xfer_complete = 1'b0;
    link_power_state = 2'b00;
    transaction_type = 2'b00;
    sequence_number = seq_num;

    // Link state machine
    case (link_state)
        LINK_RESET: begin
            link_command = 2'b01;  // Reset
            if (link_up)
                next_state = LINK_POLLING;
        end

        LINK_POLLING: begin
            link_command = 2'b10;  // Polling
            if (link_status == 2'b11)
                next_state = LINK_U0;
        end

        LINK_U0: begin
            link_power_state = 2'b00;
            // Protocol handling in U0 state
            case (protocol_state)
                PROTOCOL_IDLE: begin
                    if (packet_valid) begin
                        case ({setup_stage, direction})
                            2'b10: next_state = PROTOCOL_SETUP;
                            2'b00: next_state = PROTOCOL_DATA_OUT;
                            2'b01: next_state = PROTOCOL_DATA_IN;
                        endcase
                    end

                    // Power management
                    if (timeout_counter > 10000)  // Idle timeout
                        next_state = LINK_U1;
                end

                PROTOCOL_SETUP: begin
                    transaction_type = 2'b00;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_DATA_OUT: begin
                    transaction_type = 2'b01;
                    if (credit_count[endpoint] > 0)
                        next_state = PACKET_HEADER;
                    else
                        next_state = FLOW_WAIT;
                end

                PROTOCOL_DATA_IN: begin
                    transaction_type = 2'b01;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_STATUS: begin
                    transaction_type = 2'b10;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_PING: begin
                    transaction_type = 2'b11;
                    next_state = PACKET_HEADER;
                end

                PACKET_HEADER: begin
                    // Send packet header
                    case (transaction_type)
                        2'b00: rx_data[0] = {PTYPE_SETUP, device_address, endpoint, seq_num};
                        2'b01: rx_data[0] = {PTYPE_DATA, device_address, endpoint, seq_num};
                        2'b10: rx_data[0] = {PTYPE_ERDY, device_address, endpoint, seq_num};
                        2'b11: rx_data[0] = {PTYPE_PING, device_address, endpoint, seq_num};
                    endcase

                    if (packet_length > 0)
                        next_state = PACKET_DATA;
                    else
                        next_state = PACKET_CRC;
                end

                PACKET_DATA: begin
                    // Transfer data payload
                    for (int i = 0; i < packet_length; i++)
                        rx_data[i+1] = packet_data[i];

                    data_phase <= data_phase + 1;
                    if (data_phase >= packet_length - 1)
                        next_state = PACKET_CRC;
                end

                PACKET_CRC: begin
                    // CRC generation and check
                    next_state = PACKET_ACK;
                end

                PACKET_ACK: begin
                    rx_valid = 1'b1;
                    rx_length = packet_length;
                    rx_endpoint = endpoint;
                    rx_device = device_address;

                    case (transaction_type)
                        2'b00: next_state = PROTOCOL_STATUS;
                        2'b01: begin
                            if (data_phase == 5'b11111)  // Max burst
                                next_state = PROTOCOL_STATUS;
                            else if (direction)
                                next_state = PROTOCOL_DATA_IN;
                            else
                                next_state = PROTOCOL_DATA_OUT;
                        end
                        2'b10: begin
                            data_xfer_complete = 1'b1;
                            next_state = PROTOCOL_IDLE;
                        end
                    endcase
                end

                PACKET_NACK: begin
                    if (retry_count < 3)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RETRY;
                end

                PACKET_STALL: begin
                    next_state = PROTOCOL_IDLE;
                end

                FLOW_WAIT: begin
                    if (credit_count[endpoint] > 0)
                        next_state = PROTOCOL_DATA_OUT;
                    else if (timeout_counter > 1000)
                        next_state = PROTOCOL_PING;
                end

                FLOW_CREDIT_UPDATE: begin
                    next_state = PROTOCOL_DATA_OUT;
                end

                ERROR_RETRY: begin
                    if (retry_counter < 100)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RECOVERY;
                end

                ERROR_RECOVERY: begin
                    link_command = 2'b11;  // Recovery
                    next_state = LINK_RECOVERY;
                end

                ERROR_TIMEOUT: begin
                    if (timeout_counter > 10000)
                        next_state = LINK_RECOVERY;
                end
            endcase
        end

        LINK_U1: begin
            link_power_state = 2'b01;
            link_command = 2'b01;  // Sleep
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U2: begin
            link_power_state = 2'b10;
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U3: begin
            link_power_state = 2'b11;
            // Wake on activity
        end

        LINK_RECOVERY: begin
            if (link_status == 2'b11)
                next_state = LINK_U0;
            else if (retry_counter > 1000)
                next_state = LINK_HOT_RESET;
        end

        LINK_HOT_RESET: begin
            link_command = 2'b00;  // Reset
            next_state = LINK_RESET;
        end
    endcase
end

endmodule,"module usb3_protocol_layer_asserts  (input logic clk,

module axi_stream_fifo_monitor (
    input logic s_axis_aclk,           // Slave clock (write domain)
    input logic m_axis_aclk,           // Master clock (read domain)
    input logic s_axis_aresetn,        // Slave reset
    input logic m_axis_aresetn,        // Master reset

    // Slave interface (write)
    input logic [63:0] s_axis_tdata,
    input logic [7:0] s_axis_tkeep,
    input logic s_axis_tvalid,
    input logic s_axis_tlast,
    output logic s_axis_tready,

    // Master interface (read)
    output logic [63:0] m_axis_tdata,
    output logic [7:0] m_axis_tkeep,
    output logic m_axis_tvalid,
    output logic m_axis_tlast,
    input logic m_axis_tready,

    // Status outputs (synchronous to s_axis_aclk)
    output logic [9:0] fifo_fill_level,
    output logic fifo_empty,
    output logic fifo_full,
    output logic fifo_almost_empty,
    output logic fifo_almost_full,
    output logic [31:0] frame_count,
    output logic [31:0] byte_count,
    output logic overflow_error,
    output logic underflow_error
);

//-------------------------------------------------------------------------
// Parameters
//-------------------------------------------------------------------------
parameter FIFO_DEPTH = 1024;
parameter ALMOST_EMPTY_THRESH = 32;
parameter ALMOST_FULL_THRESH = 992;

//-------------------------------------------------------------------------
// Dual-port RAM declaration
//-------------------------------------------------------------------------
typedef struct packed {
    logic [63:0] data;
    logic [7:0] keep;
    logic last;
} fifo_entry_t;

fifo_entry_t fifo_ram [0:FIFO_DEPTH-1];

//-------------------------------------------------------------------------
// Write domain logic (s_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] wr_ptr_reg, wr_ptr_next;
logic [9:0] rd_ptr_sync1, rd_ptr_sync2, rd_ptr_sync3;
logic [31:0] frame_count_reg, frame_count_next;
logic [31:0] byte_count_reg, byte_count_next;
logic overflow_reg, overflow_next;

always_ff @(posedge s_axis_aclk or negedge s_axis_aresetn) begin
    if (!s_axis_aresetn) begin
        wr_ptr_reg <= 10'b0;
        frame_count_reg <= 32'b0;
        byte_count_reg <= 32'b0;
        overflow_reg <= 1'b0;
        rd_ptr_sync1 <= 10'b0;
        rd_ptr_sync2 <= 10'b0;
        rd_ptr_sync3 <= 10'b0;
    end else begin
        wr_ptr_reg <= wr_ptr_next;
        frame_count_reg <= frame_count_next;
        byte_count_reg <= byte_count_next;
        overflow_reg <= overflow_next;

        // Synchronize read pointer to write clock domain
        rd_ptr_sync1 <= rd_ptr_reg;
        rd_ptr_sync2 <= rd_ptr_sync1;
        rd_ptr_sync3 <= rd_ptr_sync2;
    end
end

// Write pointer management
logic [9:0] write_space;
assign write_space = (rd_ptr_sync3 > wr_ptr_reg) ?
                     (rd_ptr_sync3 - wr_ptr_reg - 1) :
                     (FIFO_DEPTH - (wr_ptr_reg - rd_ptr_sync3) - 1);

always_comb begin
    wr_ptr_next = wr_ptr_reg;
    frame_count_next = frame_count_reg;
    byte_count_next = byte_count_reg;
    overflow_next = overflow_reg;
    s_axis_tready = (write_space > 0);

    if (s_axis_tvalid && s_axis_tready) begin
        // Write to FIFO
        fifo_ram[wr_ptr_reg].data <= s_axis_tdata;
        fifo_ram[wr_ptr_reg].keep <= s_axis_tkeep;
        fifo_ram[wr_ptr_reg].last <= s_axis_tlast;

        wr_ptr_next = wr_ptr_reg + 1;
        byte_count_next = byte_count_reg + $countones(s_axis_tkeep);

        if (s_axis_tlast)
            frame_count_next = frame_count_reg + 1;
    end

    // Overflow detection
    if (s_axis_tvalid && !s_axis_tready)
        overflow_next = 1'b1;
    else if (overflow_reg && !s_axis_tvalid)
        overflow_next = 1'b0;
end

//-------------------------------------------------------------------------
// Read domain logic (m_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] rd_ptr_reg, rd_ptr_next;
logic [9:0] wr_ptr_sync1, wr_ptr_sync2, wr_ptr_sync3;
logic underflow_reg, underflow_next;

always_ff @(posedge m_axis_aclk or negedge m_axis_aresetn) begin
    if (!m_axis_aresetn) begin
        rd_ptr_reg <= 10'b0;
        underflow_reg <= 1'b0;
        wr_ptr_sync1 <= 10'b0;
        wr_ptr_sync2 <= 10'b0;
        wr_ptr_sync3 <= 10'b0;
    end else begin
        rd_ptr_reg <= rd_ptr_next;
        underflow_reg <= underflow_next;

        // Synchronize write pointer to read clock domain
        wr_ptr_sync1 <= wr_ptr_reg;
        wr_ptr_sync2 <= wr_ptr_sync1;
        wr_ptr_sync3 <= wr_ptr_sync2;
    end
end

// Read pointer management
logic [9:0] available_data;
assign available_data = (wr_ptr_sync3 >= rd_ptr_reg) ?
                        (wr_ptr_sync3 - rd_ptr_reg) :
                        (FIFO_DEPTH - (rd_ptr_reg - wr_ptr_sync3));

always_comb begin
    rd_ptr_next = rd_ptr_reg;
    underflow_next = underflow_reg;
    m_axis_tvalid = (available_data > 0);
    m_axis_tdata = fifo_ram[rd_ptr_reg].data;
    m_axis_tkeep = fifo_ram[rd_ptr_reg].keep;
    m_axis_tlast = fifo_ram[rd_ptr_reg].last;

    if (m_axis_tready && m_axis_tvalid) begin
        rd_ptr_next = rd_ptr_reg + 1;
    end

    // Underflow detection
    if (m_axis_tready && !m_axis_tvalid)
        underflow_next = 1'b1;
    else if (underflow_reg && m_axis_tvalid)
        underflow_next = 1'b0;
end

//-------------------------------------------------------------------------
// Status calculation (synchronous to s_axis_aclk)
//-------------------------------------------------------------------------
logic [9:0] fill_level;
logic [9:0] rd_ptr_stable;

always_ff @(posedge s_axis_aclk or negedge s_axis_aresetn) begin
    if (!s_axis_aresetn) begin
        fifo_fill_level <= 10'b0;
        fifo_empty <= 1'b1;
        fifo_full <= 1'b0;
        fifo_almost_empty <= 1'b1;
        fifo_almost_full <= 1'b0;
        frame_count <= 32'b0;
        byte_count <= 32'b0;
        overflow_error <= 1'b0;
    end else begin
        // Use synchronized read pointer for stable status
        rd_ptr_stable = rd_ptr_sync3;

        // Calculate fill level
        if (wr_ptr_reg >= rd_ptr_stable)
            fill_level = wr_ptr_reg - rd_ptr_stable;
        else
            fill_level = FIFO_DEPTH - (rd_ptr_stable - wr_ptr_reg);

        fifo_fill_level <= fill_level;
        fifo_empty <= (fill_level == 0);
        fifo_full <= (fill_level == FIFO_DEPTH - 1);
        fifo_almost_empty <= (fill_level <= ALMOST_EMPTY_THRESH);
        fifo_almost_full <= (fill_level >= ALMOST_FULL_THRESH);

        // Update status registers
        frame_count <= frame_count_reg;
        byte_count <= byte_count_reg;
        overflow_error <= overflow_reg;
        underflow_error <= underflow_reg;
    end
end

endmodule,"module axi_stream_fifo_monitor_asserts  (input logic s_axis_aclk, input logic m_axis_aclk, input logic s_axis_aresetn, input logic m_axis_aresetn,

module memory_controller #(
    parameter ADDR_WIDTH = 16,
    parameter DATA_WIDTH = 32,
    parameter ECC_WIDTH = 7,  // Hamming code for 32-bit data
    parameter NUM_MASTERS = 4
) (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Master interfaces
    input  logic [NUM_MASTERS-1:0]        master_req,
    input  logic [NUM_MASTERS-1:0][ADDR_WIDTH-1:0] master_addr,
    input  logic [NUM_MASTERS-1:0]        master_rw,  // 1=write, 0=read
    input  logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_wdata,
    output logic [NUM_MASTERS-1:0]        master_grant,
    output logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_rdata,
    output logic [NUM_MASTERS-1:0]        master_ack,

    // Memory interface
    output logic                          mem_cs,
    output logic                          mem_we,
    output logic [ADDR_WIDTH-1:0]         mem_addr,
    output logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_wdata,
    input  logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_rdata,
    input  logic                          mem_rdy
);

    // Internal state
    typedef enum logic [2:0] {
        IDLE,
        ARB_WAIT,
        CMD_SEND,
        DATA_WAIT,
        DATA_CAPTURE,
        ECC_CHECK,
        RESPONSE
    } state_t;

    state_t current_state, next_state;

    // Arbitration and request tracking
    logic [NUM_MASTERS-1:0] req_latched;
    logic [NUM_MASTERS-1:0] req_priority;
    logic [NUM_MASTERS-1:0] grant_current;
    logic [ADDR_WIDTH-1:0]  active_addr;
    logic                   active_rw;
    logic [DATA_WIDTH-1:0]  active_wdata;
    logic [NUM_MASTERS-1:0] active_master;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_encoded_data;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_decoded_data;
    logic [ECC_WIDTH-1:0]   ecc_syndrome;
    logic                   ecc_error;
    logic                   ecc_corrected;

    // Counter for timing
    logic [2:0] wait_counter;
    logic [2:0] wait_target;

    // Pipeline registers
    logic [DATA_WIDTH-1:0] response_data;
    logic [NUM_MASTERS-1:0] response_master;
    logic response_valid;

    //------------------------------------------------------------------------
    // Combinational: Priority encoder for arbitration (using case statements)
    //------------------------------------------------------------------------
    always_comb begin
        req_priority = '0;

        // Fixed priority: Master 0 > Master 1 > Master 2 > Master 3
        // Using nested case statements for priority encoding
        casez (req_latched)
            4'b???1: req_priority = 4'b0001;
            4'b??10: req_priority = 4'b0010;
            4'b?100: req_priority = 4'b0100;
            4'b1000: req_priority = 4'b1000;
            default: req_priority = 4'b0000;
        endcase
    end

    //------------------------------------------------------------------------
    // Combinational: Next state logic
    //------------------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (|req_latched) begin
                    next_state = ARB_WAIT;
                end
            end

            ARB_WAIT: begin
                if (req_priority != '0) begin
                    next_state = CMD_SEND;
                end
            end

            CMD_SEND: begin
                if (mem_rdy) begin
                    next_state = (active_rw) ? DATA_WAIT : DATA_CAPTURE;
                end
            end

            DATA_WAIT: begin
                if (wait_counter == wait_target) begin
                    next_state = DATA_CAPTURE;
                end
            end

            DATA_CAPTURE: begin
                if (mem_rdy) begin
                    next_state = (active_rw) ? RESPONSE : ECC_CHECK;
                end
            end

            ECC_CHECK: begin
                next_state = RESPONSE;
            end

            RESPONSE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------------
    // Sequential: Main state machine (positive edge)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            req_latched <= '0;
            active_master <= '0;
            active_addr <= '0;
            active_rw <= 1'b0;
            active_wdata <= '0;
            wait_counter <= '0;
            wait_target <= '0;
            response_data <= '0;
            response_master <= '0;
            response_valid <= 1'b0;
            grant_current <= '0;
        end
        else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    // Latch all requests
                    req_latched <= master_req;
                    grant_current <= '0;
                    response_valid <= 1'b0;
                    wait_counter <= '0;
                end

                ARB_WAIT: begin
                    // Nothing to do, waiting for priority resolution
                end

                CMD_SEND: begin
                    if (mem_rdy) begin
                        // Clear granted request
                        req_latched <= req_latched & ~grant_current;
                        wait_counter <= '0;

                        // Set timing based on operation type
                        case (active_rw)
                            1'b1: wait_target <= 3'd3;  // Write latency
                            1'b0: wait_target <= 3'd2;  // Read latency
                        endcase
                    end
                end

                DATA_WAIT: begin
                    wait_counter <= wait_counter + 1'b1;
                end

                DATA_CAPTURE: begin
                    if (mem_rdy) begin
                        if (!active_rw) begin
                            // Store read data for ECC check
                            response_data <= ecc_decoded_data[DATA_WIDTH-1:0];
                            response_master <= active_master;
                            response_valid <= 1'b1;
                        end
                    end
                end

                ECC_CHECK: begin
                    // ECC check is combinational, just state transition
                end

                RESPONSE: begin
                    // Generate response signals
                    case (grant_current)
                        4'b0001: master_ack = 4'b0001;
                        4'b0010: master_ack = 4'b0010;
                        4'b0100: master_ack = 4'b0100;
                        4'b1000: master_ack = 4'b1000;
                        default: master_ack = 4'b0000;
                    endcase
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Sequential: Grant generation and active request tracking (positive edge)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_current <= '0;
            active_master <= '0;
            active_addr <= '0;
            active_rw <= 1'b0;
            active_wdata <= '0;
        end
        else begin
            case (current_state)
                IDLE: begin
                    grant_current <= '0;
                end

                ARB_WAIT: begin
                    if (req_priority != '0) begin
                        grant_current <= req_priority;

                        // Capture active request details using case
                        case (req_priority)
                            4'b0001: begin
                                active_master <= 4'b0001;
                                active_addr <= master_addr[0];
                                active_rw <= master_rw[0];
                                active_wdata <= master_wdata[0];
                            end
                            4'b0010: begin
                                active_master <= 4'b0010;
                                active_addr <= master_addr[1];
                                active_rw <= master_rw[1];
                                active_wdata <= master_wdata[1];
                            end
                            4'b0100: begin
                                active_master <= 4'b0100;
                                active_addr <= master_addr[2];
                                active_rw <= master_rw[2];
                                active_wdata <= master_wdata[2];
                            end
                            4'b1000: begin
                                active_master <= 4'b1000;
                                active_addr <= master_addr[3];
                                active_rw <= master_rw[3];
                                active_wdata <= master_wdata[3];
                            end
                            default: begin
                                active_master <= '0;
                                active_addr <= '0;
                                active_rw <= 1'b0;
                                active_wdata <= '0;
                            end
                        endcase
                    end
                end

                default: begin
                    // Hold values during operation
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Sequential: ECC encoding for write data (falling edge for pipelining)
    //------------------------------------------------------------------------
    always_ff @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ecc_encoded_data <= '0;
        end
        else begin
            case (current_state)
                CMD_SEND: begin
                    if (active_rw) begin
                        // Generate Hamming code for 32-bit data
                        ecc_encoded_data[DATA_WIDTH-1:0] <= active_wdata;
                        ecc_encoded_data[DATA_WIDTH +: ECC_WIDTH] <= {
                            ^(active_wdata & 32'hAAAAAAAA),  // Even parity for bit0
                            ^(active_wdata & 32'hCCCCCCCC),  // Even parity for bit1
                            ^(active_wdata & 32'hF0F0F0F0),  // Even parity for bit2
                            ^(active_wdata & 32'hFF00FF00),  // Even parity for bit3
                            ^(active_wdata & 32'hFFFF0000),  // Even parity for bit4
                            ^(active_wdata & 32'hFFFFFFFF),  // Overall parity
                            ^(active_wdata & 32'hF0F0F0F0) ^ ^(active_wdata & 32'h0F0F0F0F)
                        };
                    end
                end
                default: begin
                    // Hold
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Combinational: ECC decoding and error detection
    //------------------------------------------------------------------------
    always_comb begin
        ecc_syndrome = '0;
        ecc_error = 1'b0;
        ecc_corrected = 1'b0;
        ecc_decoded_data = mem_rdata;

        // Calculate syndrome using case for each bit
        casez (mem_rdata)
            default: begin
                ecc_syndrome[0] = ^mem_rdata[31:0] ^ mem_rdata[32];
                ecc_syndrome[1] = ^(mem_rdata[31:0] & 32'hAAAAAAAA) ^ mem_rdata[33];
                ecc_syndrome[2] = ^(mem_rdata[31:0] & 32'hCCCCCCCC) ^ mem_rdata[34];
                ecc_syndrome[3] = ^(mem_rdata[31:0] & 32'hF0F0F0F0) ^ mem_rdata[35];
                ecc_syndrome[4] = ^(mem_rdata[31:0] & 32'hFF00FF00) ^ mem_rdata[36];
                ecc_syndrome[5] = ^(mem_rdata[31:0] & 32'hFFFF0000) ^ mem_rdata[37];
                ecc_syndrome[6] = ^mem_rdata ^ mem_rdata[38];
            end
        endcase

        // Error detection and correction
        if (ecc_syndrome != '0) begin
            ecc_error = 1'b1;
            case (ecc_syndrome)
                7'b0000001: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[0] = ~mem_rdata[0];
                end
                7'b0000010: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[1] = ~mem_rdata[1];
                end
                7'b0000100: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[2] = ~mem_rdata[2];
                end
                // Additional cases would cover all 32 data bits and ECC bits
                default: begin
                    // Multi-bit error, cannot correct
                    ecc_corrected = 1'b0;
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Combinational: Output assignments
    //------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        master_grant = '0;
        mem_cs = 1'b0;
        mem_we = 1'b0;
        mem_addr = '0;
        mem_wdata = '0;

        case (current_state)
            IDLE: begin
                // No memory activity
            end

            ARB_WAIT: begin
                // Grant signals to masters
                master_grant = req_priority;
            end

            CMD_SEND: begin
                if (mem_rdy) begin
                    mem_cs = 1'b1;
                    mem_we = active_rw;
                    mem_addr = active_addr;
                    if (active_rw) begin
                        mem_wdata = ecc_encoded_data;
                    end
                end
            end

            DATA_CAPTURE: begin
                if (mem_rdy) begin
                    mem_cs = 1'b1;
                    mem_we = active_rw;
                    mem_addr = active_addr;
                end
            end

            RESPONSE: begin
                // Return data to requesting master
                case (response_master)
                    4'b0001: master_rdata[0] = response_data;
                    4'b0010: master_rdata[1] = response_data;
                    4'b0100: master_rdata[2] = response_data;
                    4'b1000: master_rdata[3] = response_data;
                    default: master_rdata = '0;
                endcase
                master_ack = response_valid ? response_master : '0;
            end

            default: begin
                // Default values
            end
        endcase
    end

endmodule,"module memory_controller_asserts # (parameter ADDR_WIDTH = 16,

module nand_flash_controller (
    input logic clk,
    input logic rst_n,

    // Host interface
    input logic [31:0] flash_addr,
    input logic [11:0] page_size,           // 512B to 16KB
    input logic read_req,
    input logic write_req,
    input logic erase_req,
    input logic [2047:0] write_data,        // Page data
    output logic [2047:0] read_data,
    output logic read_valid,
    output logic write_done,
    output logic erase_done,
    output logic busy,

    // NAND interface
    output logic [15:0] nand_addr,
    output logic [7:0] nand_cmd,
    inout logic [7:0] nand_data,
    output logic nand_cle,                   // Command latch enable
    output logic nand_ale,                   // Address latch enable
    output logic nand_ce_n,                   // Chip enable
    output logic nand_we_n,                   // Write enable
    output logic nand_re_n,                   // Read enable
    input logic nand_rdy,                     // Ready/Busy
    input logic nand_wp_n,                     // Write protect

    // ECC interface
    output logic [12:0] ecc_parity [0:127],   // BCH parity bits
    input logic [12:0] ecc_correction [0:127],
    input logic [6:0] error_count,
    input logic uncorrectable_error,

    // Bad block management
    output logic [15:0] bad_block_table [0:1023],
    output logic block_erasable,
    output logic wear_level_index
);

typedef enum logic [5:0] {
    IDLE,
    READ_PAGE_CMD,
    READ_ADDR_CYCLE1,
    READ_ADDR_CYCLE2,
    READ_ADDR_CYCLE3,
    READ_ADDR_CYCLE4,
    READ_ADDR_CYCLE5,
    READ_WAIT_RDY,
    READ_DATA_TRANSFER,
    READ_ECC_CALC,
    READ_ECC_CORRECT,
    READ_STATUS,

    WRITE_PAGE_CMD,
    WRITE_ADDR_CYCLE1,
    WRITE_ADDR_CYCLE2,
    WRITE_ADDR_CYCLE3,
    WRITE_ADDR_CYCLE4,
    WRITE_ADDR_CYCLE5,
    WRITE_DATA_TRANSFER,
    WRITE_ECC_GEN,
    WRITE_CONFIRM_CMD,
    WRITE_WAIT_RDY,
    WRITE_STATUS,

    ERASE_BLOCK_CMD,
    ERASE_ADDR_CYCLE1,
    ERASE_ADDR_CYCLE2,
    ERASE_ADDR_CYCLE3,
    ERASE_CONFIRM_CMD,
    ERASE_WAIT_RDY,
    ERASE_STATUS,

    BAD_BLOCK_CHECK,
    BAD_BLOCK_MARK,
    WEAR_LEVELING,
    GARBAGE_COLLECT,

    RESET_CMD,
    RESET_WAIT,
    GET_FEATURES,
    SET_FEATURES,

    ERROR_HANDLING,
    RETRY_OPERATION
} state_t;

state_t state, next_state;
logic [31:0] page_address;
logic [15:0] column_address;
logic [15:0] row_address;
logic [12:0] page_counter;
logic [7:0] status_register;
logic [2:0] retry_count;
logic ecc_enabled;
logic [12:0] generated_parity [0:127];
logic [2047:0] data_buffer;
logic [3:0] addr_cycle_count;

// NAND command codes
parameter CMD_READ_PAGE     = 8'h00;
parameter CMD_READ_CONFIRM  = 8'h30;
parameter CMD_WRITE_PAGE    = 8'h80;
parameter CMD_WRITE_CONFIRM = 8'h10;
parameter CMD_ERASE_BLOCK   = 8'h60;
parameter CMD_ERASE_CONFIRM = 8'hD0;
parameter CMD_READ_STATUS   = 8'h70;
parameter CMD_RESET         = 8'hFF;
parameter CMD_GET_FEATURES  = 8'hEE;
parameter CMD_SET_FEATURES  = 8'hEF;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        page_address <= 32'b0;
        column_address <= 16'b0;
        row_address <= 16'b0;
        page_counter <= 13'b0;
        retry_count <= 3'b0;
        addr_cycle_count <= 4'b0;

        for (int i = 0; i < 128; i++) begin
            ecc_parity[i] <= 13'b0;
            generated_parity[i] <= 13'b0;
        end

    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (read_req || write_req || erase_req) begin
                    page_address <= flash_addr;
                    row_address <= flash_addr[31:16];
                    column_address <= flash_addr[15:0];
                end
            end

            READ_DATA_TRANSFER: begin
                if (page_counter < (page_size >> 3)) begin  // Convert to bytes
                    data_buffer[page_counter*8 +: 8] <= nand_data;
                    page_counter <= page_counter + 1;
                end
            end

            WRITE_DATA_TRANSFER: begin
                if (page_counter < (page_size >> 3)) begin
                    nand_data <= write_data[page_counter*8 +: 8];
                    page_counter <= page_counter + 1;
                end
            end

            READ_ECC_CALC: begin
                // Generate ECC for read data
                for (int i = 0; i < 128; i++) begin
                    generated_parity[i] <= data_buffer[i*16 +: 16] ^
                                          {16{1'b1}};  // Simplified BCH
                end
            end

            WRITE_ECC_GEN: begin
                // Generate ECC parity for write data
                for (int i = 0; i < 128; i++) begin
                    ecc_parity[i] <= write_data[i*16 +: 16] ^
                                    {16{1'b1}};  // Simplified BCH
                end
            end

            BAD_BLOCK_CHECK: begin
                if (bad_block_table[row_address[9:0]] != 0)
                    block_erasable <= 1'b0;
                else
                    block_erasable <= 1'b1;
            end

            WEAR_LEVELING: begin
                wear_level_index <= wear_level_index + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    busy = (state != IDLE);
    read_valid = 1'b0;
    write_done = 1'b0;
    erase_done = 1'b0;
    read_data = data_buffer;

    // Default NAND interface values
    nand_cle = 1'b0;
    nand_ale = 1'b0;
    nand_ce_n = 1'b0;
    nand_we_n = 1'b1;
    nand_re_n = 1'b1;
    nand_cmd = 8'b0;
    nand_addr = 16'b0;

    case (state)
        IDLE: begin
            if (read_req) begin
                next_state = BAD_BLOCK_CHECK;
            end else if (write_req) begin
                if (!bad_block_table[row_address[9:0]])
                    next_state = WRITE_PAGE_CMD;
                else
                    next_state = ERROR_HANDLING;
            end else if (erase_req) begin
                next_state = ERASE_BLOCK_CMD;
            end
        end

        // Read Operations
        READ_PAGE_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_READ_PAGE;
            next_state = READ_ADDR_CYCLE1;
        end

        READ_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[7:0];
            next_state = READ_ADDR_CYCLE2;
            addr_cycle_count = 4'd1;
        end

        READ_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[15:8];
            next_state = READ_ADDR_CYCLE3;
            addr_cycle_count = 4'd2;
        end

        READ_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = READ_ADDR_CYCLE4;
            addr_cycle_count = 4'd3;
        end

        READ_ADDR_CYCLE4: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = READ_ADDR_CYCLE5;
            addr_cycle_count = 4'd4;
        end

        READ_ADDR_CYCLE5: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};  // 3rd row cycle if needed
            next_state = READ_WAIT_RDY;
            addr_cycle_count = 4'd5;
        end

        READ_WAIT_RDY: begin
            nand_cmd = CMD_READ_CONFIRM;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_rdy) begin
                next_state = READ_DATA_TRANSFER;
                page_counter = 13'b0;
            end
        end

        READ_DATA_TRANSFER: begin
            nand_re_n = 1'b0;  // Strobe read
            if (page_counter >= (page_size >> 3) - 1) begin
                next_state = READ_ECC_CALC;
            end
        end

        READ_ECC_CALC: begin
            next_state = READ_ECC_CORRECT;
        end

        READ_ECC_CORRECT: begin
            if (uncorrectable_error) begin
                next_state = ERROR_HANDLING;
            end else if (error_count > 0) begin
                // Apply ECC corrections
                for (int i = 0; i < 128; i++) begin
                    if (ecc_correction[i] != 0)
                        data_buffer[i*16 +: 16] <=
                            data_buffer[i*16 +: 16] ^ ecc_correction[i];
                end
            end
            next_state = READ_STATUS;
        end

        READ_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            status_register = nand_data;
            if (status_register[0]) begin  // Check pass/fail
                read_valid = 1'b1;
                next_state = IDLE;
                rx_packets[0] <= rx_packets[0] + 1;
            end else begin
                if (retry_count < 3)
                    next_state = READ_PAGE_CMD;
                else
                    next_state = ERROR_HANDLING;
            end
        end

        // Write Operations
        WRITE_PAGE_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_WRITE_PAGE;
            next_state = WRITE_ADDR_CYCLE1;
        end

        WRITE_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[7:0];
            next_state = WRITE_ADDR_CYCLE2;
        end

        WRITE_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = column_address[15:8];
            next_state = WRITE_ADDR_CYCLE3;
        end

        WRITE_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = WRITE_ADDR_CYCLE4;
        end

        WRITE_ADDR_CYCLE4: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = WRITE_ADDR_CYCLE5;
        end

        WRITE_ADDR_CYCLE5: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};
            next_state = WRITE_DATA_TRANSFER;
            page_counter = 13'b0;
        end

        WRITE_DATA_TRANSFER: begin
            nand_we_n = 1'b0;
            if (page_counter >= (page_size >> 3) - 1) begin
                next_state = WRITE_ECC_GEN;
            end
        end

        WRITE_ECC_GEN: begin
            next_state = WRITE_CONFIRM_CMD;
        end

        WRITE_CONFIRM_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_WRITE_CONFIRM;
            next_state = WRITE_WAIT_RDY;
        end

        WRITE_WAIT_RDY: begin
            if (nand_rdy) begin
                next_state = WRITE_STATUS;
            end
        end

        WRITE_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_data[0]) begin  // Pass
                write_done = 1'b1;
                tx_packets[0] <= tx_packets[0] + 1;
                next_state = IDLE;
            end else begin
                if (retry_count < 3)
                    next_state = WRITE_PAGE_CMD;
                else begin
                    next_state = BAD_BLOCK_MARK;
                end
            end
        end

        // Erase Operations
        ERASE_BLOCK_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_ERASE_BLOCK;
            next_state = ERASE_ADDR_CYCLE1;
        end

        ERASE_ADDR_CYCLE1: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[7:0];
            next_state = ERASE_ADDR_CYCLE2;
        end

        ERASE_ADDR_CYCLE2: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = row_address[15:8];
            next_state = ERASE_ADDR_CYCLE3;
        end

        ERASE_ADDR_CYCLE3: begin
            nand_ale = 1'b1;
            nand_we_n = 1'b0;
            nand_addr = {8'b0, row_address[23:16]};
            next_state = ERASE_CONFIRM_CMD;
        end

        ERASE_CONFIRM_CMD: begin
            nand_cle = 1'b1;
            nand_we_n = 1'b0;
            nand_cmd = CMD_ERASE_CONFIRM;
            next_state = ERASE_WAIT_RDY;
        end

        ERASE_WAIT_RDY: begin
            if (nand_rdy) begin
                next_state = ERASE_STATUS;
            end
        end

        ERASE_STATUS: begin
            nand_cmd = CMD_READ_STATUS;
            nand_cle = 1'b1;
            nand_we_n = 1'b0;

            if (nand_data[0]) begin
                erase_done = 1'b1;
                next_state = IDLE;
            end else begin
                next_state = ERROR_HANDLING;
            end
        end

        BAD_BLOCK_CHECK: begin
            if (bad_block_table[row_address[9:0]] == 0)
                next_state = READ_PAGE_CMD;
            else
                next_state = ERROR_HANDLING;
        end

        BAD_BLOCK_MARK: begin
            bad_block_table[row_address[9:0]] <= 16'hFFFF;
            next_state = IDLE;
        end

        WEAR_LEVELING: begin
            // Swap static and dynamic data blocks
            next_state = IDLE;
        end

        GARBAGE_COLLECT: begin
            // Copy valid pages to new block
            next_state = IDLE;
        end

        ERROR_HANDLING: begin
            if (retry_count < 3) begin
                retry_count <= retry_count + 1;
                next_state = RETRY_OPERATION;
            end else begin
                next_state = IDLE;
            end
        end

        RETRY_OPERATION: begin
            next_state = READ_PAGE_CMD;  // Default retry
        end
    endcase
end

endmodule,"module nand_flash_controller_asserts  (input logic clk,

//------------------------------------------------------------------------------
// AXI4-Lite to APB Bridge Module
// Converts AXI4-Lite transactions to APB protocol.
// Supports configurable data width (32/64-bit) and up to 16 address slaves.
//------------------------------------------------------------------------------
module axi_lite_to_apb #(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 32,
    parameter NUM_SLAVES = 4,
    // APB timing parameters
    parameter P_SETUP_CYCLES = 1,   // Setup cycles in PSELx to PENABLE
    parameter P_ENABLE_CYCLES = 1   // Cycles PENABLE stays high
) (
    // AXI4-Lite Interface
    input  logic                     ACLK,
    input  logic                     ARESETn,
    // AXI Write Address Channel
    input  logic [ADDR_WIDTH-1:0]    AWADDR,
    input  logic [2:0]               AWPROT,
    input  logic                     AWVALID,
    output logic                     AWREADY,
    // AXI Write Data Channel
    input  logic [DATA_WIDTH-1:0]    WDATA,
    input  logic [DATA_WIDTH/8-1:0]  WSTRB,
    input  logic                     WVALID,
    output logic                     WREADY,
    // AXI Write Response Channel
    output logic [1:0]               BRESP,
    output logic                     BVALID,
    input  logic                     BREADY,
    // AXI Read Address Channel
    input  logic [ADDR_WIDTH-1:0]    ARADDR,
    input  logic [2:0]               ARPROT,
    input  logic                     ARVALID,
    output logic                     ARREADY,
    // AXI Read Data Channel
    output logic [DATA_WIDTH-1:0]    RDATA,
    output logic [1:0]               RRESP,
    output logic                     RVALID,
    input  logic                     RREADY,

    // APB Interface
    output logic [ADDR_WIDTH-1:0]    PADDR,
    output logic                     PSELx,
    output logic                     PENABLE,
    output logic                     PWRITE,
    output logic [DATA_WIDTH-1:0]    PWDATA,
    output logic [DATA_WIDTH/8-1:0]  PSTRB,
    input  logic [DATA_WIDTH-1:0]    PRDATA,
    input  logic                     PREADY,
    input  logic                     PSLVERR
);

    // State machine encoding
    typedef enum logic [2:0] {
        IDLE        = 3'b000,
        WR_SETUP    = 3'b001,
        WR_ENABLE   = 3'b010,
        WR_RESPONSE = 3'b011,
        RD_SETUP    = 3'b100,
        RD_ENABLE   = 3'b101,
        RD_RESPONSE = 3'b110
    } state_t;

    state_t state, next_state;

    // Address decoding for slave select
    logic [NUM_SLAVES-1:0] addr_decode;
    logic [ADDR_WIDTH-1:0] apb_addr_reg;
    logic [DATA_WIDTH-1:0] write_data_reg;
    logic [DATA_WIDTH/8-1:0] write_strb_reg;
    logic write_op_pending, read_op_pending;
    logic [1:0] write_resp, read_resp;

    // APB timing counters
    logic [7:0] setup_cnt, enable_cnt;

    //--------------------------------------------------------------------------
    // Address decoding logic
    //--------------------------------------------------------------------------
    always_comb begin
        addr_decode = '0;
        // Simple address decoding based on top bits (assumes equally sized regions)
        for (int i = 0; i < NUM_SLAVES; i++) begin
            if (apb_addr_reg[ADDR_WIDTH-1:ADDR_WIDTH-$clog2(NUM_SLAVES)] == i)
                addr_decode[i] = 1'b1;
        end
    end

    //--------------------------------------------------------------------------
    // State machine sequential block
    //--------------------------------------------------------------------------
    always_ff @(posedge ACLK or negedge ARESETn) begin
        if (!ARESETn) begin
            state <= IDLE;
            setup_cnt <= '0;
            enable_cnt <= '0;
            apb_addr_reg <= '0;
            write_data_reg <= '0;
            write_strb_reg <= '0;
            write_op_pending <= 1'b0;
            read_op_pending <= 1'b0;
            write_resp <= 2'b00;
            read_resp <= 2'b00;
        end else begin
            state <= next_state;

            // APB timing counters
            case (state)
                WR_SETUP, RD_SETUP: begin
                    if (setup_cnt < P_SETUP_CYCLES - 1)
                        setup_cnt <= setup_cnt + 1;
                    else
                        setup_cnt <= '0;
                end
                WR_ENABLE, RD_ENABLE: begin
                    if (enable_cnt < P_ENABLE_CYCLES - 1)
                        enable_cnt <= enable_cnt + 1;
                    else
                        enable_cnt <= '0;
                end
                default: begin
                    setup_cnt <= '0;
                    enable_cnt <= '0;
                end
            endcase

            // Register APB data/address for ongoing transaction
            if (next_state == WR_SETUP && state == IDLE) begin
                apb_addr_reg <= AWADDR;
                write_data_reg <= WDATA;
                write_strb_reg <= WSTRB;
                write_op_pending <= 1'b1;
            end else if (next_state == RD_SETUP && state == IDLE) begin
                apb_addr_reg <= ARADDR;
                read_op_pending <= 1'b1;
            end

            // Capture response from APB
            if (state == WR_ENABLE && PREADY) begin
                write_resp <= PSLVERR ? 2'b10 : 2'b00; // SLVERR -> AXI SLVERR
                write_op_pending <= 1'b0;
            end else if (state == RD_ENABLE && PREADY) begin
                read_resp <= PSLVERR ? 2'b10 : 2'b00;
                read_op_pending <= 1'b0;
            end
        end
    end

    //--------------------------------------------------------------------------
    // State machine combinational block with case statements
    //--------------------------------------------------------------------------
    always_comb begin
        next_state = state;

        case (state)
            IDLE: begin
                if (AWVALID && WVALID && !write_op_pending)
                    next_state = WR_SETUP;
                else if (ARVALID && !read_op_pending)
                    next_state = RD_SETUP;
            end

            WR_SETUP: begin
                if (setup_cnt == P_SETUP_CYCLES - 1)
                    next_state = WR_ENABLE;
            end

            WR_ENABLE: begin
                if (PREADY && (enable_cnt == P_ENABLE_CYCLES - 1))
                    next_state = WR_RESPONSE;
            end

            WR_RESPONSE: begin
                if (BREADY)
                    next_state = IDLE;
            end

            RD_SETUP: begin
                if (setup_cnt == P_SETUP_CYCLES - 1)
                    next_state = RD_ENABLE;
            end

            RD_ENABLE: begin
                if (PREADY && (enable_cnt == P_ENABLE_CYCLES - 1))
                    next_state = RD_RESPONSE;
            end

            RD_RESPONSE: begin
                if (RREADY)
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //--------------------------------------------------------------------------
    // APB control signals using case statements
    //--------------------------------------------------------------------------
    always_comb begin
        // Default values
        PSELx = 1'b0;
        PENABLE = 1'b0;
        PWRITE = 1'b0;
        PADDR = apb_addr_reg;
        PWDATA = write_data_reg;
        PSTRB = write_strb_reg;

        case (state)
            WR_SETUP: begin
                PSELx = |addr_decode;
                PENABLE = 1'b0;
                PWRITE = 1'b1;
            end
            WR_ENABLE: begin
                PSELx = |addr_decode;
                PENABLE = 1'b1;
                PWRITE = 1'b1;
            end
            RD_SETUP: begin
                PSELx = |addr_decode;
                PENABLE = 1'b0;
                PWRITE = 1'b0;
            end
            RD_ENABLE: begin
                PSELx = |addr_decode;
                PENABLE = 1'b1;
                PWRITE = 1'b0;
            end
            default: begin
                PSELx = 1'b0;
                PENABLE = 1'b0;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // AXI handshake and response logic with case statements
    //--------------------------------------------------------------------------
    always_comb begin
        // Default values
        AWREADY = 1'b0;
        WREADY = 1'b0;
        ARREADY = 1'b0;
        BVALID = 1'b0;
        RVALID = 1'b0;
        BRESP = 2'b00;
        RRESP = 2'b00;
        RDATA = '0;

        case (state)
            IDLE: begin
                AWREADY = 1'b1;
                WREADY = 1'b1;
                ARREADY = 1'b1;
            end

            WR_RESPONSE: begin
                BVALID = 1'b1;
                case (write_resp)
                    2'b00: BRESP = 2'b00; // OKAY
                    2'b10: BRESP = 2'b10; // SLVERR
                    default: BRESP = 2'b11; // DECERR
                endcase
            end

            RD_RESPONSE: begin
                RVALID = 1'b1;
                case (read_resp)
                    2'b00: RRESP = 2'b00; // OKAY
                    2'b10: RRESP = 2'b10; // SLVERR
                    default: RRESP = 2'b11; // DECERR
                endcase
                RDATA = PRDATA;
            end

            default: begin
                // No additional handshakes in other states
            end
        endcase
    end

endmodule,"module axi_lite_to_apb_asserts # (parameter DATA_WIDTH = 32,
